const fn supports_mutable_semantic(semantic_version: u16) -> bool {
    semantic_version >= MIN_MUTABLE_SEMANTIC_VERSION
}

const MUTABLE_V4_CLASSES: [MutableClass; 2] = [MutableClass::State, MutableClass::Record];
const MUTABLE_V5_CLASSES: [MutableClass; 3] = [
    MutableClass::State,
    MutableClass::Record,
    MutableClass::Blob,
];

fn mutable_classes_for_semantic(semantic_version: u16) -> &'static [MutableClass] {
    match semantic_version {
        MIN_BLOB_NETWORK_SEMANTIC_VERSION.. => &MUTABLE_V5_CLASSES,
        MIN_MUTABLE_SEMANTIC_VERSION.. => &MUTABLE_V4_CLASSES,
        _ => &[],
    }
}

const READY_RECONCILIATION_CLASSES: &str =
    "event,state,record,blob-v5-opt-in,event-bridge-v6-opt-in";

const fn contact_reconciliation_classes(semantic_version: u16) -> &'static str {
    if semantic_version >= MIN_EVENT_BRIDGE_SEMANTIC_VERSION {
        "event,state,record,blob,event-bridge-opt-in"
    } else if semantic_version >= MIN_BLOB_NETWORK_SEMANTIC_VERSION {
        "event,state,record,blob"
    } else {
        "event,state,record"
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct PostEventReserve {
    exchanges: usize,
    bytes: usize,
    items: usize,
}

fn post_event_reserve(semantic_version: u16) -> Option<PostEventReserve> {
    match semantic_version {
        MIN_BLOB_NETWORK_SEMANTIC_VERSION.. => Some(PostEventReserve {
            exchanges: MUTABLE_V5_CONTACT_RESERVE_EXCHANGES,
            bytes: MUTABLE_V5_CONTACT_RESERVE_BYTES,
            items: 6 * MUTABLE_LANE_GUARANTEED_ITEMS + 1,
        }),
        MIN_MUTABLE_SEMANTIC_VERSION.. => Some(PostEventReserve {
            exchanges: MUTABLE_CONTACT_RESERVE_EXCHANGES,
            bytes: MUTABLE_CONTACT_RESERVE_BYTES,
            items: 4 * MUTABLE_LANE_GUARANTEED_ITEMS,
        }),
        _ => None,
    }
}

fn selected_mutable_reconciliation_limits() -> Result<ReconciliationLimits, NodeError> {
    Ok(ReconciliationLimits::new(
        MUTABLE_RECONCILIATION_FRAME_BYTES,
        MUTABLE_RECONCILIATION_ROUNDS,
        MAX_CARDINALITY_LIMIT,
    )?)
}

fn validate_forwarding_config(forwarding: &SelectedForwardingConfig) -> Result<(), NodeError> {
    let required = forwarding
        .store_limits()
        .max_items()
        .checked_add(MAX_ROUTE_CACHE_ITEMS)
        .and_then(|items| items.checked_add(MAX_CUSTODY_RETIREMENTS))
        .ok_or_else(|| {
            NodeError::Configuration(
                "configured Event inventory capacity overflows its bounded cardinality".into(),
            )
        })?;
    let selected_cardinality =
        u64::try_from(MAX_CARDINALITY_LIMIT).expect("selected reconciliation cardinality fits u64");
    if required > selected_cardinality {
        return Err(NodeError::Configuration(format!(
            "configured live Events, route cache, and permanent custody retirements require cardinality {required}, exceeding selected reconciliation bound {selected_cardinality}"
        )));
    }
    Ok(())
}
#[cfg(unix)]
const LOCAL_ZEROIZATION_IO_DEADLINE: Duration = Duration::from_secs(10);
#[cfg(unix)]
const LOCAL_ZEROIZATION_INTEGRITY_INTERVAL: Duration = Duration::from_millis(250);
#[cfg(unix)]
const LOCAL_ZEROIZATION_DISCOVERY_INTERVAL: Duration = Duration::from_millis(50);

/// Optional source-authenticated sample application hosted by one node process.
///
/// These roles select application behavior only. They do not alter the Aster
/// Event envelope, reconciliation, carrier, or mission-session protocols.
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
pub enum NodeApplication {
    /// Replicate admitted Events without producing sample application data.
    #[default]
    Relay,
    /// Emit the virtual-mesh sample Ping exactly once from durable local state.
    PingEmitter,
    /// Emit Ping only after recipient-filtered control activates epoch two.
    EpochTwoPingEmitter,
    /// Emit one causally correlated Pong for the admitted sample Ping.
    PongResponder,
}

impl NodeApplication {
    /// Parses the stable CLI spelling for a sample application role.
    pub fn parse(value: &str) -> Result<Self, NodeError> {
        match value {
            "relay" => Ok(Self::Relay),
            "ping-emitter" => Ok(Self::PingEmitter),
            "epoch2-ping-emitter" => Ok(Self::EpochTwoPingEmitter),
            "pong-responder" => Ok(Self::PongResponder),
            _ => Err(NodeError::Configuration(format!(
                "application must be relay, ping-emitter, epoch2-ping-emitter, or pong-responder; got {value:?}"
            ))),
        }
    }

    const fn as_str(self) -> &'static str {
        match self {
            Self::Relay => "relay",
            Self::PingEmitter => "ping-emitter",
            Self::EpochTwoPingEmitter => "epoch2-ping-emitter",
            Self::PongResponder => "pong-responder",
        }
    }
}

/// Explicit virtual-mesh acceptance scenario selected by the demo CLI.
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
pub enum DemoScenario {
    /// N-instance source-authenticated Ping/Pong with temporal forwarding.
    #[default]
    PingPong,
    /// Four-role control propagation, rekey, exclusion, and Ping/Pong acceptance.
    Control,
}

impl DemoScenario {
    /// Parses the stable CLI spelling without deriving behavior from node count.
    pub fn parse(value: &str) -> Result<Self, NodeError> {
        match value {
            "ping-pong" => Ok(Self::PingPong),
            "control" => Ok(Self::Control),
            _ => Err(NodeError::Configuration(format!(
                "demo scenario must be ping-pong or control; got {value:?}"
            ))),
        }
    }
}

/// Exact carrier address and independently authenticated mission identity.
#[derive(Clone, Copy, Debug, Eq, Ord, PartialEq, PartialOrd)]
pub struct MissionExpectedPeer {
    /// Iroh carrier identity and direct address.
    pub carrier: ExpectedPeer,
    /// Authority-provisioned Aster mission identity.
    pub mission: NodeId,
}

/// Pre-provisioned carrier and mission identities whose socket locator may be
/// learned only during an explicit nearby-discovery window.
#[cfg(feature = "nearby-discovery")]
#[derive(Clone, Copy, Debug, Eq, Ord, PartialEq, PartialOrd)]
pub struct MissionNearbyPeer {
    /// Exact Iroh carrier identity; discovery cannot replace this authority.
    pub carrier: EndpointId,
    /// Independently authenticated, authority-provisioned mission identity.
    pub mission: NodeId,
}

#[cfg(feature = "nearby-discovery")]
impl fmt::Display for MissionNearbyPeer {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            formatter,
            "{}={}",
            self.carrier,
            format_node_id(self.mission)
        )
    }
}

#[cfg(feature = "nearby-discovery")]
impl FromStr for MissionNearbyPeer {
    type Err = NodeError;

    fn from_str(value: &str) -> Result<Self, Self::Err> {
        let (carrier, mission) = value.split_once('=').ok_or_else(|| {
            NodeError::Configuration("nearby peer must be CARRIER_ID=MISSION_NODE_ID_HEX64".into())
        })?;
        if mission.contains('=') {
            return Err(NodeError::Configuration(
                "nearby peer contains more than one mission identity separator".into(),
            ));
        }
        Ok(Self {
            carrier: carrier.parse().map_err(|error| {
                NodeError::Configuration(format!("invalid nearby carrier id: {error}"))
            })?,
            mission: parse_node_id(mission)?,
        })
    }
}

