    fn live_blob_request(
        operation_key: &[u8],
        topic: &Topic,
        scope: &Scope,
    ) -> crate::application::BlobPublishRequest {
        crate::application::BlobPublishRequest {
            operation_key: operation_key.to_vec(),
            topic: topic.clone(),
            scope: scope.clone(),
            priority: Priority::Priority,
            media_type: Some("application/x-aster-runtime-test".into()),
            schema_id: b"runtime/blob-v1".to_vec(),
        }
    }

    async fn read_live_blob_pages(
        handle: &SelectedBlobHandle,
        request: crate::application::BlobReadRequest,
    ) -> Vec<u8> {
        let mut offset = 0u64;
        let mut output = Vec::new();
        loop {
            let page = handle
                .read_page(crate::application::BlobReadPageRequest {
                    blob: request.clone(),
                    offset,
                    max_bytes: crate::application::MAX_SELECTED_BLOB_PAGE_BYTES,
                })
                .await
                .expect("read bounded live Blob page");
            assert_eq!(page.id, request.id);
            assert_eq!(page.offset, offset);
            assert!(!page.is_empty());
            assert!(page.len() <= crate::application::MAX_SELECTED_BLOB_PAGE_BYTES);
            let next_offset = page.next_offset();
            let complete = page.complete;
            output.extend_from_slice(page.as_bytes());
            assert_eq!(next_offset, output.len() as u64);
            if complete {
                assert_eq!(next_offset, page.total_len);
                break;
            }
            offset = next_offset;
        }
        output
    }

    fn prefill_status_commands(
        sender: &mpsc::Sender<SelectedApplicationCommand>,
    ) -> Vec<oneshot::Receiver<Result<SelectedEventStatus, crate::application::ApplicationError>>>
    {
        let mut responses = Vec::with_capacity(APPLICATION_COMMAND_CAPACITY);
        for _ in 0..APPLICATION_COMMAND_CAPACITY {
            let (response, received) = oneshot::channel();
            assert!(
                sender
                    .try_send(SelectedApplicationCommand::Event(
                        SelectedEventCommand::Status { response },
                    ))
                    .is_ok(),
                "pre-fill bounded application queue"
            );
            responses.push(received);
        }
        assert_eq!(sender.capacity(), 0);
        responses
    }

    enum QueuedApplicationResponse {
        Event(oneshot::Receiver<Result<SelectedEventStatus, crate::application::ApplicationError>>),
        State(
            oneshot::Receiver<
                Result<crate::application::StateProjection, crate::application::ApplicationError>,
            >,
        ),
        Record(
            oneshot::Receiver<
                Result<crate::application::RecordProjection, crate::application::ApplicationError>,
            >,
        ),
        Blob(
            oneshot::Receiver<
                Result<crate::application::BlobReadPage, crate::application::ApplicationError>,
            >,
        ),
    }

    fn prefill_mixed_application_commands(
        sender: &mpsc::Sender<SelectedApplicationCommand>,
    ) -> Vec<QueuedApplicationResponse> {
        use crate::application::{BlobReadPageRequest, BlobReadRequest, RecordQuery, StateQuery};

        let topic = Topic::new("opaque").expect("topic");
        let scope = Scope::new("test/runtime").expect("scope");
        let mut responses = Vec::with_capacity(APPLICATION_COMMAND_CAPACITY);
        for index in 0..APPLICATION_COMMAND_CAPACITY {
            let queued = match index % 4 {
                0 => {
                    let (response, received) = oneshot::channel();
                    sender
                        .try_send(SelectedApplicationCommand::Event(
                            SelectedEventCommand::Status { response },
                        ))
                        .expect("pre-fill Event command");
                    QueuedApplicationResponse::Event(received)
                }
                1 => {
                    let (response, received) = oneshot::channel();
                    sender
                        .try_send(SelectedApplicationCommand::State(
                            SelectedStateCommand::Query {
                                query: StateQuery {
                                    topic: topic.clone(),
                                    scope: scope.clone(),
                                    logical_key: format!("queued-state-{index}").into_bytes(),
                                    include_recoverable_versions: false,
                                },
                                response,
                            },
                        ))
                        .expect("pre-fill State command");
                    QueuedApplicationResponse::State(received)
                }
                2 => {
                    let (response, received) = oneshot::channel();
                    sender
                        .try_send(SelectedApplicationCommand::Record(
                            SelectedRecordCommand::Query {
                                query: RecordQuery {
                                    topic: topic.clone(),
                                    scope: scope.clone(),
                                    logical_key: format!("queued-record-{index}").into_bytes(),
                                    include_superseded_versions: false,
                                },
                                response,
                            },
                        ))
                        .expect("pre-fill Record command");
                    QueuedApplicationResponse::Record(received)
                }
                _ => {
                    let (response, received) = oneshot::channel();
                    sender
                        .try_send(SelectedApplicationCommand::Blob(
                            SelectedBlobCommand::ReadPage {
                                request: BlobReadPageRequest {
                                    blob: BlobReadRequest {
                                        id: crate::application::BlobId::from_bytes(
                                            [u8::try_from(index).expect("queue index fits u8"); 32],
                                        ),
                                        topic: topic.clone(),
                                        scope: scope.clone(),
                                    },
                                    offset: 0,
                                    max_bytes: 1,
                                },
                                response,
                            },
                        ))
                        .expect("pre-fill Blob command");
                    QueuedApplicationResponse::Blob(received)
                }
            };
            responses.push(queued);
        }
        assert_eq!(sender.capacity(), 0);
        responses
    }

    async fn assert_explicit_mixed_application_responses(
        responses: Vec<QueuedApplicationResponse>,
    ) -> (usize, usize) {
        use crate::application::ApplicationErrorKind;

        let mut successes = 0usize;
        let mut unavailable = 0usize;
        for response in responses {
            match response {
                QueuedApplicationResponse::Event(response) => match response
                    .await
                    .expect("queued Event caller receives an explicit result")
                {
                    Ok(_) => successes += 1,
                    Err(error) => {
                        unavailable += 1;
                        assert_eq!(error.kind(), ApplicationErrorKind::StateUnavailable);
                        assert_eq!(error.operation(), "status");
                    }
                },
                QueuedApplicationResponse::State(response) => match response
                    .await
                    .expect("queued State caller receives an explicit result")
                {
                    Ok(projection) => {
                        successes += 1;
                        assert!(projection.current.is_none());
                        assert!(projection.recoverable.is_empty());
                    }
                    Err(error) => {
                        unavailable += 1;
                        assert_eq!(error.kind(), ApplicationErrorKind::StateUnavailable);
                        assert_eq!(error.operation(), "state query");
                    }
                },
                QueuedApplicationResponse::Record(response) => match response
                    .await
                    .expect("queued Record caller receives an explicit result")
                {
                    Ok(projection) => {
                        successes += 1;
                        assert!(projection.current.is_none());
                        assert!(projection.concurrent.is_empty());
                        assert!(projection.superseded.is_empty());
                        assert!(projection.conflict.is_none());
                    }
                    Err(error) => {
                        unavailable += 1;
                        assert_eq!(error.kind(), ApplicationErrorKind::StateUnavailable);
                        assert_eq!(error.operation(), "record query");
                    }
                },
                QueuedApplicationResponse::Blob(response) => match response
                    .await
                    .expect("queued Blob caller receives an explicit result")
                {
                    Ok(page) => {
                        successes += 1;
                        assert_eq!(page.len(), 1);
                    }
                    Err(error) if error.kind() == ApplicationErrorKind::StateUnavailable => {
                        unavailable += 1;
                        assert_eq!(error.operation(), "blob read page");
                    }
                    Err(error) => {
                        successes += 1;
                        assert_eq!(error.operation(), "blob read page");
                        assert!(matches!(
                            error.kind(),
                            ApplicationErrorKind::RequestRejected
                                | ApplicationErrorKind::UnauthorizedOrRevoked
                                | ApplicationErrorKind::PolicyUnsettled
                                | ApplicationErrorKind::ResourceLimit
                        ));
                    }
                },
            }
        }
        (successes, unavailable)
    }

    async fn assert_explicit_status_responses(
        responses: Vec<
            oneshot::Receiver<Result<SelectedEventStatus, crate::application::ApplicationError>>,
        >,
    ) -> (usize, usize) {
        use crate::application::{ApplicationErrorKind, EventSyncStatus};

        let mut successes = 0usize;
        let mut unavailable = 0usize;
        for response in responses {
            match response
                .await
                .expect("queued caller receives an explicit result")
            {
                Ok(status) => {
                    successes += 1;
                    assert!(matches!(
                        status.sync,
                        EventSyncStatus::Offline
                            | EventSyncStatus::AwaitingAuthenticatedContact
                            | EventSyncStatus::LastContactComplete
                            | EventSyncStatus::WorkRemained
                            | EventSyncStatus::PolicyChangedSinceContact
                    ));
                }
                Err(error) => {
                    unavailable += 1;
                    assert_eq!(error.kind(), ApplicationErrorKind::StateUnavailable);
                    assert_eq!(error.operation(), "status");
                }
            }
        }
        (successes, unavailable)
    }

    fn spawn_saturated_status_callers(
        callers: &mut JoinSet<usize>,
        selected: &SelectedEventHandle,
        authenticated_contact_observed: Arc<AtomicBool>,
    ) {
        use crate::application::ApplicationErrorKind;

        for _ in 0..APPLICATION_COMMAND_CAPACITY * 2 {
            let selected = selected.clone();
            let authenticated_contact_observed = authenticated_contact_observed.clone();
            callers.spawn(async move {
                let mut successes = 0usize;
                loop {
                    match selected.status().await {
                        Ok(status) => {
                            successes = successes.saturating_add(1);
                            if status.authenticated_contacts > 0 {
                                authenticated_contact_observed.store(true, Ordering::Release);
                            }
                        }
                        Err(error) => {
                            assert_eq!(error.kind(), ApplicationErrorKind::StateUnavailable);
                            assert_eq!(error.operation(), "status");
                            return successes;
                        }
                    }
                }
            });
        }
    }

    #[tokio::test]
    async fn oversized_run_for_is_rejected_before_readiness_or_state_mutation() {
        let state = root("oversized-run-for");
        let (application_sender, application_receiver) =
            mpsc::channel(APPLICATION_COMMAND_CAPACITY);
        let application_admission = Arc::new(AtomicBool::new(true));
        let (shutdown_sender, shutdown_receiver) = mpsc::channel(1);
        let (ready_sender, ready_receiver) = oneshot::channel();
        let actor = tokio::spawn(run_node_actor(
            NodeConfig {
                state: state.clone(),
                bind: SocketAddr::from(([127, 0, 0, 1], 0)),
                mission: test_mission(),
                peers: Vec::new(),
                mutable_interests: Default::default(),
                sync_interval: Duration::from_secs(60),
                run_for: Some(Duration::MAX),
                application: NodeApplication::Relay,
            },
            application_receiver,
            application_admission,
            shutdown_receiver,
            ready_sender,
        ));
        let error = timeout(Duration::from_secs(5), actor)
            .await
            .expect("oversized run_for rejection deadline")
            .expect("actor must return an error rather than panic")
            .expect_err("oversized run_for must fail");
        assert!(
            matches!(&error, NodeError::Configuration(message) if message.contains("run_for exceeds the monotonic clock")),
            "unexpected oversized run_for error: {error}"
        );
        assert!(
            ready_receiver.await.is_err(),
            "oversized run_for must fail before readiness"
        );
        assert!(
            !state.exists(),
            "oversized run_for must fail before state mutation"
        );

        drop(application_sender);
        drop(shutdown_sender);
    }

    #[tokio::test]
    async fn run_for_preempts_a_saturated_application_queue_and_closes_every_caller() {
        use crate::application::ApplicationErrorKind;

        let state = root("run-for-saturated-application-queue");
        let mission = test_mission();
        let identity = mission.identity();
        let mission_authority = mission.mission_authority_id();
        let (application_sender, application_receiver) =
            mpsc::channel(APPLICATION_COMMAND_CAPACITY);
        let application_admission = Arc::new(AtomicBool::new(true));
        let selected = SelectedEventHandle::new(
            application_sender.clone(),
            application_admission.clone(),
            identity,
            mission_authority,
        );
        let selected_state = SelectedStateHandle::new(
            application_sender.clone(),
            application_admission.clone(),
            identity,
            mission_authority,
        );
        let selected_record = SelectedRecordHandle::new(
            application_sender.clone(),
            application_admission.clone(),
            identity,
            mission_authority,
        );
        let selected_blob = SelectedBlobHandle::new(
            application_sender.clone(),
            application_admission.clone(),
            identity,
            mission_authority,
        );
        let responses = prefill_mixed_application_commands(&application_sender);

        let (shutdown_sender, shutdown_receiver) = mpsc::channel(1);
        let (ready_sender, ready_receiver) = oneshot::channel();
        let actor = tokio::spawn(run_node_actor(
            NodeConfig {
                state: state.clone(),
                bind: SocketAddr::from(([127, 0, 0, 1], 0)),
                mission,
                peers: Vec::new(),
                mutable_interests: Default::default(),
                sync_interval: Duration::from_secs(60),
                run_for: Some(Duration::from_millis(250)),
                application: NodeApplication::Relay,
            },
            application_receiver,
            application_admission.clone(),
            shutdown_receiver,
            ready_sender,
        ));
        let mut callers = JoinSet::new();
        spawn_saturated_status_callers(&mut callers, &selected, Arc::new(AtomicBool::new(false)));
        let state_pressure = {
            use crate::application::StateQuery;

            let selected_state = selected_state.clone();
            tokio::spawn(async move {
                let query = StateQuery {
                    topic: Topic::new("opaque").expect("topic"),
                    scope: Scope::new("test/runtime").expect("scope"),
                    logical_key: b"saturated-state".to_vec(),
                    include_recoverable_versions: false,
                };
                let mut successes = 0usize;
                loop {
                    match selected_state.query(query.clone()).await {
                        Ok(projection) => {
                            successes = successes.saturating_add(1);
                            assert!(projection.current.is_none());
                            assert!(projection.recoverable.is_empty());
                        }
                        Err(error) => {
                            assert_eq!(error.kind(), ApplicationErrorKind::StateUnavailable);
                            assert_eq!(error.operation(), "state query");
                            return successes;
                        }
                    }
                }
            })
        };
        let record_pressure = {
            use crate::application::RecordQuery;

            let selected_record = selected_record.clone();
            tokio::spawn(async move {
                let query = RecordQuery {
                    topic: Topic::new("opaque").expect("topic"),
                    scope: Scope::new("test/runtime").expect("scope"),
                    logical_key: b"saturated-record".to_vec(),
                    include_superseded_versions: false,
                };
                let mut successes = 0usize;
                loop {
                    match selected_record.query(query.clone()).await {
                        Ok(projection) => {
                            successes = successes.saturating_add(1);
                            assert!(projection.current.is_none());
                            assert!(projection.concurrent.is_empty());
                            assert!(projection.superseded.is_empty());
                            assert!(projection.conflict.is_none());
                        }
                        Err(error) => {
                            assert_eq!(error.kind(), ApplicationErrorKind::StateUnavailable);
                            assert_eq!(error.operation(), "record query");
                            return successes;
                        }
                    }
                }
            })
        };
        ready_receiver.await.expect("actor readiness");
        let receipt = timeout(Duration::from_secs(5), actor)
            .await
            .expect("run_for must not be starved by saturated commands")
            .expect("actor task")
            .expect("actor completion");
        assert_eq!(receipt.contacts, 0);
        assert_eq!(receipt.contact_errors, 0);
        assert!(!application_admission.load(Ordering::Acquire));

        let (successes, unavailable) = assert_explicit_mixed_application_responses(responses).await;
        assert_eq!(successes + unavailable, APPLICATION_COMMAND_CAPACITY);
        let expected_callers = APPLICATION_COMMAND_CAPACITY * 2;
        let (completed_callers, pressure_successes) = timeout(Duration::from_secs(5), async {
            let mut completed = 0usize;
            let mut successes = 0usize;
            while let Some(result) = callers.join_next().await {
                completed += 1;
                successes = successes.saturating_add(result.expect("status pressure task"));
            }
            (completed, successes)
        })
        .await
        .expect("every saturated status caller closes explicitly");
        assert_eq!(completed_callers, expected_callers);
        let state_pressure_successes = timeout(Duration::from_secs(5), state_pressure)
            .await
            .expect("saturated State caller closes explicitly")
            .expect("State pressure task");
        let record_pressure_successes = timeout(Duration::from_secs(5), record_pressure)
            .await
            .expect("saturated Record caller closes explicitly")
            .expect("Record pressure task");
        assert!(
            successes + pressure_successes + state_pressure_successes + record_pressure_successes
                > 0,
            "the nonzero run_for interval must admit work before its deadline"
        );
        assert!(
            unavailable + completed_callers > 0,
            "the run_for deadline must close callers with StateUnavailable"
        );
        let closed = selected
            .status()
            .await
            .expect_err("retained handle closes with the actor");
        assert_eq!(closed.kind(), ApplicationErrorKind::StateUnavailable);
        assert_eq!(closed.operation(), "status");
        let closed = selected_state
            .query(crate::application::StateQuery {
                topic: Topic::new("opaque").expect("topic"),
                scope: Scope::new("test/runtime").expect("scope"),
                logical_key: b"closed-state".to_vec(),
                include_recoverable_versions: false,
            })
            .await
            .expect_err("retained State handle closes with the actor");
        assert_eq!(closed.kind(), ApplicationErrorKind::StateUnavailable);
        assert_eq!(closed.operation(), "state query");
        let closed = selected_record
            .query(crate::application::RecordQuery {
                topic: Topic::new("opaque").expect("topic"),
                scope: Scope::new("test/runtime").expect("scope"),
                logical_key: b"closed-record".to_vec(),
                include_superseded_versions: false,
            })
            .await
            .expect_err("retained Record handle closes with the actor");
        assert_eq!(closed.kind(), ApplicationErrorKind::StateUnavailable);
        assert_eq!(closed.operation(), "record query");
        let closed = selected_blob
            .read_page(crate::application::BlobReadPageRequest {
                blob: crate::application::BlobReadRequest {
                    id: crate::application::BlobId::from_bytes([0x5b; 32]),
                    topic: Topic::new("opaque").expect("topic"),
                    scope: Scope::new("test/runtime").expect("scope"),
                },
                offset: 0,
                max_bytes: 1,
            })
            .await
            .expect_err("retained Blob handle closes with the actor");
        assert_eq!(closed.kind(), ApplicationErrorKind::StateUnavailable);
        assert_eq!(closed.operation(), "blob read page");

        drop(selected);
        drop(selected_state);
        drop(selected_record);
        drop(selected_blob);
        drop(application_sender);
        drop(shutdown_sender);
        fs::remove_dir_all(state).expect("cleanup saturated application state");
    }

    #[tokio::test]
    async fn authenticated_contact_status_progresses_with_saturated_application_queues() {
        let root = root("authenticated-contact-saturated-application-queues");
        let left_state = root.join("left");
        let right_state = root.join("right");
        let mut issued = issue_missions(2);
        let right_mission = issued.pop().expect("right mission");
        let left_mission = issued.pop().expect("left mission");
        let left_mission_id = left_mission.identity;
        let right_mission_id = right_mission.identity;
        let left_mission_authority = left_mission.credentials.mission_authority_id();
        let right_mission_authority = right_mission.credentials.mission_authority_id();
        let left_carrier = {
            let identity =
                NodeIdentity::load_or_create(&left_state).expect("left carrier identity");
            let carrier = identity.id();
            drop(identity);
            carrier
        };
        let right_carrier = {
            let identity =
                NodeIdentity::load_or_create(&right_state).expect("right carrier identity");
            let carrier = identity.id();
            drop(identity);
            carrier
        };
        let (left_sender, left_receiver) = mpsc::channel(APPLICATION_COMMAND_CAPACITY);
        let left_admission = Arc::new(AtomicBool::new(true));
        let left_selected = SelectedEventHandle::new(
            left_sender.clone(),
            left_admission.clone(),
            left_mission_id,
            left_mission_authority,
        );
        let left_prefilled = prefill_status_commands(&left_sender);
        let (left_shutdown, left_shutdown_receiver) = mpsc::channel(1);
        let (left_ready, left_readiness) = oneshot::channel();

        let (right_sender, right_receiver) = mpsc::channel(APPLICATION_COMMAND_CAPACITY);
        let right_admission = Arc::new(AtomicBool::new(true));
        let right_selected = SelectedEventHandle::new(
            right_sender.clone(),
            right_admission.clone(),
            right_mission_id,
            right_mission_authority,
        );
        let right_prefilled = prefill_status_commands(&right_sender);
        let (right_shutdown, right_shutdown_receiver) = mpsc::channel(1);
        let (right_ready, right_readiness) = oneshot::channel();

        let left_contact_observed = Arc::new(AtomicBool::new(false));
        let right_contact_observed = Arc::new(AtomicBool::new(false));
        let mut callers = JoinSet::new();
        spawn_saturated_status_callers(&mut callers, &left_selected, left_contact_observed.clone());
        spawn_saturated_status_callers(
            &mut callers,
            &right_selected,
            right_contact_observed.clone(),
        );
        let placeholder = SocketAddr::from(([127, 0, 0, 1], 9));
        let (left_actor, right_actor) = if left_carrier > right_carrier {
            let left_actor = tokio::spawn(run_node_actor(
                NodeConfig {
                    state: left_state,
                    bind: SocketAddr::from(([127, 0, 0, 1], 0)),
                    mission: left_mission.credentials,
                    peers: vec![MissionExpectedPeer {
                        carrier: ExpectedPeer {
                            id: right_carrier,
                            address: placeholder,
                        },
                        mission: right_mission_id,
                    }],
                    mutable_interests: Default::default(),
                    sync_interval: Duration::from_nanos(1),
                    run_for: None,
                    application: NodeApplication::Relay,
                },
                left_receiver,
                left_admission.clone(),
                left_shutdown_receiver,
                left_ready,
            ));
            let left_address = timeout(Duration::from_secs(10), left_readiness)
                .await
                .expect("left responder becomes ready")
                .expect("left responder readiness")
                .bound_sockets
                .into_iter()
                .find(SocketAddr::is_ipv4)
                .expect("left responder IPv4 endpoint");
            let right_actor = tokio::spawn(run_node_actor(
                NodeConfig {
                    state: right_state,
                    bind: SocketAddr::from(([127, 0, 0, 1], 0)),
                    mission: right_mission.credentials,
                    peers: vec![MissionExpectedPeer {
                        carrier: ExpectedPeer {
                            id: left_carrier,
                            address: left_address,
                        },
                        mission: left_mission_id,
                    }],
                    mutable_interests: Default::default(),
                    sync_interval: Duration::from_nanos(1),
                    run_for: None,
                    application: NodeApplication::Relay,
                },
                right_receiver,
                right_admission.clone(),
                right_shutdown_receiver,
                right_ready,
            ));
            timeout(Duration::from_secs(10), right_readiness)
                .await
                .expect("right initiator becomes ready")
                .expect("right initiator readiness");
            (left_actor, right_actor)
        } else {
            let right_actor = tokio::spawn(run_node_actor(
                NodeConfig {
                    state: right_state,
                    bind: SocketAddr::from(([127, 0, 0, 1], 0)),
                    mission: right_mission.credentials,
                    peers: vec![MissionExpectedPeer {
                        carrier: ExpectedPeer {
                            id: left_carrier,
                            address: placeholder,
                        },
                        mission: left_mission_id,
                    }],
                    mutable_interests: Default::default(),
                    sync_interval: Duration::from_nanos(1),
                    run_for: None,
                    application: NodeApplication::Relay,
                },
                right_receiver,
                right_admission.clone(),
                right_shutdown_receiver,
                right_ready,
            ));
            let right_address = timeout(Duration::from_secs(10), right_readiness)
                .await
                .expect("right responder becomes ready")
                .expect("right responder readiness")
                .bound_sockets
                .into_iter()
                .find(SocketAddr::is_ipv4)
                .expect("right responder IPv4 endpoint");
            let left_actor = tokio::spawn(run_node_actor(
                NodeConfig {
                    state: left_state,
                    bind: SocketAddr::from(([127, 0, 0, 1], 0)),
                    mission: left_mission.credentials,
                    peers: vec![MissionExpectedPeer {
                        carrier: ExpectedPeer {
                            id: right_carrier,
                            address: right_address,
                        },
                        mission: right_mission_id,
                    }],
                    mutable_interests: Default::default(),
                    sync_interval: Duration::from_nanos(1),
                    run_for: None,
                    application: NodeApplication::Relay,
                },
                left_receiver,
                left_admission.clone(),
                left_shutdown_receiver,
                left_ready,
            ));
            timeout(Duration::from_secs(10), left_readiness)
                .await
                .expect("left initiator becomes ready")
                .expect("left initiator readiness");
            (left_actor, right_actor)
        };

        timeout(Duration::from_secs(35), async {
            loop {
                if left_contact_observed.load(Ordering::Acquire)
                    && right_contact_observed.load(Ordering::Acquire)
                {
                    break;
                }
                sleep(Duration::from_millis(10)).await;
            }
        })
        .await
        .expect("authenticated completion and status must outrank saturated commands");

        left_admission.store(false, Ordering::Release);
        right_admission.store(false, Ordering::Release);
        let (left_shutdown_result, right_shutdown_result) =
            tokio::join!(left_shutdown.send(()), right_shutdown.send(()));
        assert!(left_shutdown_result.is_ok());
        assert!(right_shutdown_result.is_ok());
        let (left_receipt, right_receipt) = timeout(Duration::from_secs(10), async {
            let (left, right) = tokio::join!(left_actor, right_actor);
            (
                left.expect("left actor task")
                    .expect("left actor completion"),
                right
                    .expect("right actor task")
                    .expect("right actor completion"),
            )
        })
        .await
        .expect("saturated actors shut down promptly");
        assert!(left_receipt.contacts > 0);
        assert!(right_receipt.contacts > 0);
        let (left_successes, left_unavailable) =
            assert_explicit_status_responses(left_prefilled).await;
        let (right_successes, right_unavailable) =
            assert_explicit_status_responses(right_prefilled).await;
        assert_eq!(
            left_successes + left_unavailable,
            APPLICATION_COMMAND_CAPACITY
        );
        assert_eq!(
            right_successes + right_unavailable,
            APPLICATION_COMMAND_CAPACITY
        );

        let expected_callers = APPLICATION_COMMAND_CAPACITY * 4;
        let (completed_callers, successful_statuses) = timeout(Duration::from_secs(5), async {
            let mut completed = 0usize;
            let mut successes = 0usize;
            while let Some(result) = callers.join_next().await {
                completed += 1;
                successes = successes.saturating_add(result.expect("status pressure task"));
            }
            (completed, successes)
        })
        .await
        .expect("all saturated status callers close explicitly");
        assert_eq!(completed_callers, expected_callers);
        assert!(successful_statuses > 0);

        drop(left_selected);
        drop(right_selected);
        drop(left_sender);
        drop(right_sender);
        drop(left_shutdown);
        drop(right_shutdown);
        fs::remove_dir_all(root).expect("cleanup saturated contact state");
    }

    #[tokio::test]
    async fn live_selected_event_actor_is_peerless_durable_and_closes_admission() {
        use crate::application::{
            ApplicationErrorKind, EventAcknowledgement, EventGapQuery, EventPollRequest,
            EventPublishRequest, EventQuery, EventSubscriptionRequest, EventSyncStatus,
            EventUnsubscribe,
        };

        let state = root("live-selected-event-actor");
        let scope = Scope::new("test/runtime").expect("scope");
        let topic = Topic::new("opaque").expect("topic");
        let running = start_node(NodeConfig {
            state: state.clone(),
            bind: SocketAddr::from(([127, 0, 0, 1], 0)),
            mission: test_mission(),
            peers: Vec::new(),
            mutable_interests: Default::default(),
            sync_interval: Duration::from_millis(10),
            run_for: None,
            application: NodeApplication::Relay,
        })
        .await
        .expect("start live selected Event actor");
        let selected = running.selected_events();
        assert_eq!(
            selected.status().await.expect("peerless status").sync,
            EventSyncStatus::Offline
        );

        let subscription = selected
            .subscribe(EventSubscriptionRequest {
                operation_key: b"runtime-live-subscription".to_vec(),
                topic: topic.clone(),
                scope: scope.clone(),
                include_descendant_scopes: false,
            })
            .await
            .expect("subscribe while live");
        let published = selected
            .publish(EventPublishRequest {
                operation_key: b"runtime-live-publish".to_vec(),
                predecessor: None,
                topic: topic.clone(),
                scope: scope.clone(),
                priority: Priority::Priority,
                logical_key: b"runtime-live-key".to_vec(),
                payload: b"published while peerless".to_vec(),
                tombstone: false,
            })
            .await
            .expect("publish while live");
        let queried = selected
            .query(EventQuery {
                after_acceptance_marker: 0,
                limit: 8,
                topic: Some(topic.clone()),
                scope: Some(scope.clone()),
                ..EventQuery::default()
            })
            .await
            .expect("query while live");
        assert_eq!(queried.items.len(), 1);
        assert_eq!(queried.items[0].id, published.id);

        let delivered = selected
            .poll(EventPollRequest {
                subscription: subscription.id,
                delivery_limit: 8,
                scan_limit: 8,
            })
            .await
            .expect("poll while live");
        assert_eq!(delivered.deliveries.len(), 1);
        assert_eq!(delivered.deliveries[0].event.id, published.id);
        assert_eq!(delivered.deliveries[0].attempt, 1);
        assert_eq!(
            selected
                .acknowledge(subscription.id, published.id)
                .await
                .expect("acknowledge while live"),
            EventAcknowledgement::Acknowledged
        );
        assert!(
            selected
                .poll(EventPollRequest {
                    subscription: subscription.id,
                    delivery_limit: 8,
                    scan_limit: 8,
                })
                .await
                .expect("poll after acknowledgement")
                .deliveries
                .is_empty()
        );

        let gaps = selected
            .gaps(EventGapQuery {
                publisher: selected.identity(),
                topic: topic.clone(),
                scope: scope.clone(),
                after_sequence: 0,
                scan_limit: 8,
            })
            .await
            .expect("authenticated gap projection");
        assert!(gaps.gaps.is_empty());
        assert_eq!(gaps.scanned_through_sequence, published.event_sequence);
        assert!(!gaps.has_more);
        let beyond_high_water = selected
            .gaps(EventGapQuery {
                publisher: selected.identity(),
                topic,
                scope,
                after_sequence: published.event_sequence + 10,
                scan_limit: 8,
            })
            .await
            .expect("empty gap scan beyond high-water");
        assert!(beyond_high_water.gaps.is_empty());
        assert_eq!(
            beyond_high_water.scanned_through_sequence,
            published.event_sequence + 10
        );
        assert_eq!(
            selected
                .unsubscribe(subscription.id)
                .await
                .expect("unsubscribe while live"),
            EventUnsubscribe::Removed
        );
        assert_eq!(
            selected
                .unsubscribe(subscription.id)
                .await
                .expect("idempotent unsubscribe while live"),
            EventUnsubscribe::AlreadyAbsent
        );

        let retained = selected.clone();
        let receipt = running.shutdown().await.expect("graceful shutdown");
        assert_eq!(receipt.events, 1);
        assert_eq!(
            retained
                .status()
                .await
                .expect_err("closed actor rejects retained handle")
                .kind(),
            ApplicationErrorKind::StateUnavailable
        );
        fs::remove_dir_all(state).expect("cleanup live actor state");
    }

    #[tokio::test]
    async fn live_selected_blob_is_bounded_durable_idempotent_and_closes_admission() {
        use crate::application::{ApplicationErrorKind, BlobReadRequest};

        let root = root("live-selected-blob-actor");
        let state = root.join("state");
        fs::create_dir_all(&root).expect("live Blob root");
        let source_path = root.join("source.bin");
        let changed_path = root.join("changed.bin");
        let bytes = (0..(2 * aster_mesh::SELECTED_BLOB_CHUNK_SIZE as usize + 73))
            .map(|index| (index % 251) as u8)
            .collect::<Vec<_>>();
        let mut changed = bytes.clone();
        changed[17] ^= 0x80;
        fs::write(&source_path, &bytes).expect("write live Blob source");
        fs::write(&changed_path, changed).expect("write conflicting Blob source");
        let topic = Topic::new("opaque").expect("topic");
        let scope = Scope::new("test/runtime").expect("scope");
        let request = live_blob_request(b"runtime-live-blob-publish", &topic, &scope);
        let shared_variant_request =
            live_blob_request(b"runtime-live-blob-shared-variant", &topic, &scope);
        let mission = test_mission();
        let restart_mission = mission.clone();
        let running = start_node(NodeConfig {
            state: state.clone(),
            bind: SocketAddr::from(([127, 0, 0, 1], 0)),
            mission,
            peers: Vec::new(),
            mutable_interests: Default::default(),
            sync_interval: Duration::from_millis(10),
            run_for: None,
            application: NodeApplication::Relay,
        })
        .await
        .expect("start live selected Blob actor");
        let blobs = running.selected_blobs();
        assert_eq!(blobs.identity(), running.selected_events().identity());
        assert_eq!(
            blobs.mission_authority(),
            running.selected_events().mission_authority()
        );

        let published = blobs
            .publish(
                request.clone(),
                File::open(&source_path).expect("open live Blob source"),
            )
            .await
            .expect("publish Blob while live");
        assert!(published.inserted);
        assert_eq!(published.total_len, bytes.len() as u64);
        assert_eq!(published.priority, Priority::Priority);
        assert_eq!(
            published.media_type.as_deref(),
            Some("application/x-aster-runtime-test")
        );
        assert_eq!(published.schema_id, b"runtime/blob-v1");

        let retried = blobs
            .publish(
                request.clone(),
                File::open(&source_path).expect("reopen exact live Blob source"),
            )
            .await
            .expect("retry exact live Blob publication");
        assert_eq!(
            retried,
            crate::application::BlobPublishResult {
                inserted: false,
                ..published.clone()
            }
        );
        let conflict = blobs
            .publish(
                request.clone(),
                File::open(&changed_path).expect("open changed live Blob source"),
            )
            .await
            .expect_err("changed bytes under one Blob operation must conflict");
        assert_eq!(conflict.kind(), ApplicationErrorKind::Conflict);
        assert_eq!(conflict.operation(), "blob publish");

        let shared_variant = blobs
            .publish(
                shared_variant_request.clone(),
                File::open(&source_path).expect("reopen shared-variant Blob source"),
            )
            .await
            .expect("publish a distinct source over the same physical variant");
        assert!(shared_variant.inserted);
        assert_eq!(shared_variant.id, published.id);
        assert!(shared_variant.publisher_counter > published.publisher_counter);
        assert!(shared_variant.acceptance_marker > published.acceptance_marker);

        let read = BlobReadRequest {
            id: published.id,
            topic: topic.clone(),
            scope: scope.clone(),
        };
        assert_eq!(read_live_blob_pages(&blobs, read.clone()).await, bytes);

        let retained = blobs.clone();
        let receipt = running.shutdown().await.expect("graceful Blob shutdown");
        assert_eq!(receipt.contacts, 0);
        assert_eq!(receipt.contact_errors, 0);
        assert_eq!(receipt.direct_contacts, 0);
        assert_eq!(receipt.relay_contacts, 0);
        assert_eq!(receipt.unknown_path_contacts, 0);
        assert_eq!(receipt.carrier_path_transitions, 0);
        assert_eq!(receipt.carrier_path_transition_saturations, 0);
        assert_eq!(receipt.blobs, 2);
        assert_eq!(receipt.blob_acceptance_markers, 2);
        assert_eq!(receipt.blob_last_acceptance_marker, 2);
        assert!(receipt.blob_sealed_bytes > 0);
        assert_eq!(receipt.blob_operations, 2);
        assert!(receipt.blob_operation_bytes > 0);
        assert_eq!(receipt.blob_variants, 1);
        assert_eq!(receipt.blob_finalized_variants, 1);
        assert_eq!(receipt.blob_committed_chunks, 3);
        assert!(receipt.blob_committed_file_bytes >= bytes.len() as u64);
        assert_eq!(
            receipt.blob_reserved_file_bytes,
            receipt.blob_committed_file_bytes
        );
        assert_eq!(receipt.pending_blobs, 0);
        assert_eq!(receipt.blob_carrier_prefixes, 0);
        assert_eq!(receipt.blob_carrier_fetch_cursors, 0);
        assert_eq!(receipt.blob_network_staging_bytes, 0);
        let closed = retained
            .read_page(crate::application::BlobReadPageRequest {
                blob: read.clone(),
                offset: 0,
                max_bytes: 1,
            })
            .await
            .expect_err("closed actor rejects retained Blob handle");
        assert_eq!(closed.kind(), ApplicationErrorKind::StateUnavailable);
        assert_eq!(closed.operation(), "blob read page");

        let stopped = inspect_store(&state).expect("inspect stopped live Blob state");
        assert_eq!(stopped.blobs, receipt.blobs);
        assert_eq!(
            stopped.blob_acceptance_markers,
            receipt.blob_acceptance_markers
        );
        assert_eq!(
            stopped.blob_last_acceptance_marker,
            receipt.blob_last_acceptance_marker
        );
        assert_eq!(stopped.blob_sealed_bytes, receipt.blob_sealed_bytes);
        assert_eq!(stopped.blob_operations, receipt.blob_operations);
        assert_eq!(stopped.blob_operation_bytes, receipt.blob_operation_bytes);
        assert_eq!(stopped.blob_variants, receipt.blob_variants);
        assert_eq!(
            stopped.blob_finalized_variants,
            receipt.blob_finalized_variants
        );
        assert_eq!(stopped.blob_committed_chunks, receipt.blob_committed_chunks);
        assert_eq!(
            stopped.blob_committed_file_bytes,
            receipt.blob_committed_file_bytes
        );
        assert_eq!(
            stopped.blob_reserved_file_bytes,
            receipt.blob_reserved_file_bytes
        );
        assert_eq!(stopped.pending_blobs, receipt.pending_blobs);
        assert_eq!(stopped.blob_carrier_prefixes, receipt.blob_carrier_prefixes);
        assert_eq!(
            stopped.blob_carrier_fetch_cursors,
            receipt.blob_carrier_fetch_cursors
        );
        assert_eq!(
            stopped.blob_network_staging_bytes,
            receipt.blob_network_staging_bytes
        );

        {
            let store = Store::open_for_mission(
                state.join(STORE_FILE),
                restart_mission.mission_authority_id(),
            )
            .expect("open stopped shared-variant Blob store");
            let startup = open_startup_event_verifier_and_cache(&store, &restart_mission)
                .expect("rebuild shared-variant startup cache");
            assert_eq!(startup.cache.blob_claim_count(), 2);
            assert_eq!(
                startup.cache.startup_blob_completion_audits(),
                1,
                "startup performs one physical completion audit per exact variant"
            );
        }

        let reopened = start_node(NodeConfig {
            state: state.clone(),
            bind: SocketAddr::from(([127, 0, 0, 1], 0)),
            mission: restart_mission,
            peers: Vec::new(),
            mutable_interests: Default::default(),
            sync_interval: Duration::from_millis(10),
            run_for: None,
            application: NodeApplication::Relay,
        })
        .await
        .expect("restart live selected Blob actor");
        let reopened_blobs = reopened.selected_blobs();
        assert_eq!(
            read_live_blob_pages(&reopened_blobs, read).await,
            bytes,
            "restart must reauthenticate and stream the exact Blob"
        );
        let restarted_retry = reopened_blobs
            .publish(
                request,
                File::open(&source_path).expect("reopen restart Blob source"),
            )
            .await
            .expect("restart-stable exact Blob retry");
        assert!(!restarted_retry.inserted);
        assert_eq!(restarted_retry.id, published.id);
        assert_eq!(
            restarted_retry.publisher_counter,
            published.publisher_counter
        );
        assert_eq!(
            restarted_retry.acceptance_marker,
            published.acceptance_marker
        );
        let restarted_shared = reopened_blobs
            .publish(
                shared_variant_request,
                File::open(&source_path).expect("reopen shared variant after restart"),
            )
            .await
            .expect("restart-stable shared-variant operation retry");
        assert!(!restarted_shared.inserted);
        assert_eq!(restarted_shared.id, shared_variant.id);
        assert_eq!(
            restarted_shared.publisher_counter,
            shared_variant.publisher_counter
        );
        assert_eq!(
            restarted_shared.acceptance_marker,
            shared_variant.acceptance_marker
        );
        let reopened_receipt = reopened
            .shutdown()
            .await
            .expect("shutdown restarted Blob actor");
        assert_eq!(reopened_receipt.blobs, receipt.blobs);
        assert_eq!(reopened_receipt.blob_operations, receipt.blob_operations);
        assert_eq!(reopened_receipt.blob_variants, receipt.blob_variants);
        assert_eq!(
            reopened_receipt.blob_committed_chunks,
            receipt.blob_committed_chunks
        );
        fs::remove_dir_all(root).expect("cleanup live Blob actor state");
    }

    #[tokio::test]
    async fn live_blob_restart_rejects_full_header_tampering_before_admission() {
        const BLOB_PUBLICATIONS: redb::TableDefinition<&[u8], &[u8]> =
            redb::TableDefinition::new("aster.semantic-blob-publications.v1");

        #[derive(Clone, Copy, Debug)]
        enum HeaderTamper {
            VariantId,
            Counter,
            CausalContext,
            Priority,
            ContentLen,
            KeyEpoch,
            RouteChunkCount,
            RouteRoot,
        }

        fn tamper_header(mut encoded: Vec<u8>, tamper: HeaderTamper) -> Vec<u8> {
            // v2 metadata: version + five 32-byte identities + lineage flag +
            // two 32-byte lineages, followed by the complete authenticated
            // header projection. Walk every variable-width field so this test
            // fails if the durable schema changes under these adversaries.
            let variant_id = 1 + 3 * 32;
            let mut cursor = 1 + 5 * 32;
            assert_eq!(encoded[cursor], 1, "fixture has both lineage bindings");
            cursor += 1 + 2 * 32;
            let priority = cursor;
            cursor += 1;
            let publisher = cursor;
            cursor += 32;
            let counter = cursor;
            cursor += 8;
            let content_len = cursor;
            cursor += 8;
            let key_epoch = cursor;
            cursor += 8;
            let route_chunk_count = cursor;
            cursor += 8;
            let route_root = cursor;
            cursor += 32;
            for _ in 0..2 {
                let len = usize::from(u16::from_be_bytes(
                    encoded[cursor..cursor + 2]
                        .try_into()
                        .expect("canonical name length"),
                ));
                cursor += 2 + len;
            }
            let context_len = cursor;
            let context_count = usize::try_from(u32::from_be_bytes(
                encoded[context_len..context_len + 4]
                    .try_into()
                    .expect("causal context length"),
            ))
            .expect("causal context length fits usize");
            let context_start = context_len + 4;
            assert_eq!(
                encoded.len(),
                context_start + context_count * 40,
                "fixture has one exact v2 Blob metadata row"
            );

            match tamper {
                HeaderTamper::VariantId => {
                    encoded[variant_id] ^= 0x80;
                }
                HeaderTamper::Counter => {
                    let current = u64::from_be_bytes(
                        encoded[counter..counter + 8]
                            .try_into()
                            .expect("counter bytes"),
                    );
                    encoded[counter..counter + 8].copy_from_slice(
                        &current
                            .checked_add(1)
                            .expect("fixture counter has increment space")
                            .to_be_bytes(),
                    );
                }
                HeaderTamper::CausalContext => {
                    let dot_publisher: [u8; 32] = encoded[publisher..publisher + 32]
                        .try_into()
                        .expect("publisher bytes");
                    let mut entries = encoded[context_start..]
                        .chunks_exact(40)
                        .map(|entry| {
                            (
                                <[u8; 32]>::try_from(&entry[..32])
                                    .expect("context publisher bytes"),
                                u64::from_be_bytes(
                                    entry[32..].try_into().expect("context counter bytes"),
                                ),
                            )
                        })
                        .collect::<Vec<_>>();
                    let mut added = [0u8; 32];
                    while added == dot_publisher
                        || entries.iter().any(|(publisher, _)| *publisher == added)
                    {
                        added[0] = added[0]
                            .checked_add(1)
                            .expect("fixture leaves a distinct context publisher");
                    }
                    entries.push((added, 1));
                    entries.sort_unstable_by_key(|(publisher, _)| *publisher);
                    encoded.truncate(context_len);
                    encoded.extend_from_slice(
                        &u32::try_from(entries.len())
                            .expect("bounded fixture context")
                            .to_be_bytes(),
                    );
                    for (publisher, counter) in entries {
                        encoded.extend_from_slice(&publisher);
                        encoded.extend_from_slice(&counter.to_be_bytes());
                    }
                }
                HeaderTamper::Priority => {
                    encoded[priority] = (encoded[priority] + 1) % 4;
                }
                HeaderTamper::ContentLen => {
                    let current = u64::from_be_bytes(
                        encoded[content_len..content_len + 8]
                            .try_into()
                            .expect("content length bytes"),
                    );
                    encoded[content_len..content_len + 8].copy_from_slice(
                        &current
                            .checked_add(1)
                            .expect("fixture content length has increment space")
                            .to_be_bytes(),
                    );
                }
                HeaderTamper::KeyEpoch => {
                    let current = u64::from_be_bytes(
                        encoded[key_epoch..key_epoch + 8]
                            .try_into()
                            .expect("key epoch bytes"),
                    );
                    encoded[key_epoch..key_epoch + 8].copy_from_slice(
                        &current
                            .checked_add(1)
                            .expect("fixture key epoch has increment space")
                            .to_be_bytes(),
                    );
                }
                HeaderTamper::RouteChunkCount => {
                    let current = u64::from_be_bytes(
                        encoded[route_chunk_count..route_chunk_count + 8]
                            .try_into()
                            .expect("route chunk-count bytes"),
                    );
                    encoded[route_chunk_count..route_chunk_count + 8].copy_from_slice(
                        &current
                            .checked_add(1)
                            .expect("fixture chunk count has increment space")
                            .to_be_bytes(),
                    );
                }
                HeaderTamper::RouteRoot => {
                    encoded[route_root] ^= 0x80;
                }
            }
            encoded
        }

        let root = root("live-blob-header-tamper");
        let state = root.join("state");
        let source = root.join("source.bin");
        fs::create_dir_all(&root).expect("Blob header tamper root");
        fs::write(&source, b"full authenticated Blob header tamper fixture")
            .expect("Blob header tamper source");
        let mission = test_mission();
        let restart_mission = mission.clone();
        let running = start_node(NodeConfig {
            state: state.clone(),
            bind: SocketAddr::from(([127, 0, 0, 1], 0)),
            mission,
            peers: Vec::new(),
            mutable_interests: Default::default(),
            sync_interval: Duration::from_millis(10),
            run_for: None,
            application: NodeApplication::Relay,
        })
        .await
        .expect("start Blob header tamper fixture");
        running
            .selected_blobs()
            .publish(
                live_blob_request(
                    b"blob-header-tamper-operation",
                    &Topic::new("opaque").expect("topic"),
                    &Scope::new("test/runtime").expect("scope"),
                ),
                File::open(&source).expect("open Blob header tamper source"),
            )
            .await
            .expect("publish Blob header tamper fixture");
        running
            .shutdown()
            .await
            .expect("stop Blob header tamper fixture");

        let (key, original) = {
            let database = redb::Database::open(state.join(STORE_FILE))
                .expect("open stopped Blob header tamper database");
            let read = database.begin_read().expect("read Blob header fixture");
            let publications = read
                .open_table(BLOB_PUBLICATIONS)
                .expect("open Blob publication table");
            let mut rows = publications.iter().expect("iterate Blob publications");
            let (key, value) = rows
                .next()
                .expect("one Blob publication")
                .expect("read Blob publication");
            assert!(rows.next().is_none(), "fixture has one Blob publication");
            (key.value().to_vec(), value.value().to_vec())
        };

        for tamper in [
            HeaderTamper::VariantId,
            HeaderTamper::Counter,
            HeaderTamper::CausalContext,
            HeaderTamper::Priority,
            HeaderTamper::ContentLen,
            HeaderTamper::KeyEpoch,
            HeaderTamper::RouteChunkCount,
            HeaderTamper::RouteRoot,
        ] {
            let encoded = tamper_header(original.clone(), tamper);
            let database = redb::Database::open(state.join(STORE_FILE))
                .expect("open stopped Blob header tamper database");
            let write = database.begin_write().expect("begin Blob header tamper");
            {
                let mut publications = write
                    .open_table(BLOB_PUBLICATIONS)
                    .expect("open Blob publication table");
                publications
                    .insert(key.as_slice(), encoded.as_slice())
                    .expect("write tampered Blob header");
            }
            write.commit().expect("commit Blob header tamper");
            drop(database);

            let error = start_node(NodeConfig {
                state: state.clone(),
                bind: SocketAddr::from(([127, 0, 0, 1], 0)),
                mission: restart_mission.clone(),
                peers: Vec::new(),
                mutable_interests: Default::default(),
                sync_interval: Duration::from_millis(10),
                run_for: None,
                application: NodeApplication::Relay,
            })
            .await
            .err()
            .unwrap_or_else(|| panic!("{tamper:?} durable Blob header tamper reached readiness"));
            assert!(
                matches!(error, NodeError::Protocol(_) | NodeError::Store(_)),
                "unexpected {tamper:?} restart error: {error}"
            );
        }
        fs::remove_dir_all(root).expect("Blob header tamper cleanup");
    }

    #[tokio::test]
    async fn live_selected_blob_rekey_retry_lineage_and_restart_are_exact() {
        use std::num::NonZeroU64;

        use crate::{
            application::{ApplicationErrorKind, BlobReadPageRequest, BlobReadRequest},
            control_admin::{RegistryGenerationWitness, ScopeRekeyRequest},
        };

        let root = root("live-selected-blob-rekey-restart");
        let state = root.join("state");
        fs::create_dir_all(&root).expect("live rekey Blob root");
        let a_path = root.join("a.bin");
        let b_path = root.join("b.bin");
        let a_bytes = (0..(aster_mesh::SELECTED_BLOB_CHUNK_SIZE as usize + 17))
            .map(|index| (index % 241) as u8)
            .collect::<Vec<_>>();
        let b_bytes = (0..(aster_mesh::SELECTED_BLOB_CHUNK_SIZE as usize + 33))
            .map(|index| (index.wrapping_mul(7) % 239) as u8)
            .collect::<Vec<_>>();
        fs::write(&a_path, &a_bytes).expect("write lineage-A Blob");
        fs::write(&b_path, &b_bytes).expect("write lineage-B Blob");
        let services = control_test_services([0xda; 32]);
        let restart_mission = services.authority.clone();
        let config = |mission| NodeConfig {
            state: state.clone(),
            bind: SocketAddr::from(([127, 0, 0, 1], 0)),
            mission,
            peers: Vec::new(),
            mutable_interests: Default::default(),
            sync_interval: Duration::from_millis(10),
            run_for: None,
            application: NodeApplication::Relay,
        };
        let running = start_node(config(services.authority.clone()))
            .await
            .expect("start Blob rekey authority");
        let blobs = running.selected_blobs();
        let controls = running.selected_controls();
        let request_a = live_blob_request(b"blob-lineage-a", &services.topic, &services.scope);
        let published_a = blobs
            .publish(
                request_a.clone(),
                File::open(&a_path).expect("open lineage-A Blob"),
            )
            .await
            .expect("publish lineage-A Blob");

        let recipients = vec![
            ScopeRekeyRecipient::member(
                services.authority.identity(),
                vec![services.topic.clone()],
            )
            .expect("authority Blob rekey recipient"),
            ScopeRekeyRecipient::member(services.member.identity(), vec![services.topic.clone()])
                .expect("member Blob rekey recipient"),
        ];
        let same_epoch = controls
            .publish_scope_rekey(
                ScopeRekeyRequest::new(
                    services.registry.clone(),
                    RegistryGenerationWitness::new(NonZeroU64::new(1).expect("nonzero")),
                    services.scope.clone(),
                    NonZeroU64::new(1).expect("nonzero"),
                    recipients.clone(),
                )
                .expect("same-epoch Blob rekey request"),
            )
            .await
            .expect("publish same-epoch Blob rekey");
        assert!(same_epoch.emitted);

        let read_a = BlobReadRequest {
            id: published_a.id,
            topic: services.topic.clone(),
            scope: services.scope.clone(),
        };
        let denied_a = blobs
            .read_page(BlobReadPageRequest {
                blob: read_a,
                offset: 0,
                max_bytes: 1,
            })
            .await
            .expect_err("historical same-epoch lineage must be withheld");
        assert_eq!(denied_a.kind(), ApplicationErrorKind::UnauthorizedOrRevoked);
        let retry_a = blobs
            .publish(
                request_a,
                File::open(&a_path).expect("reopen lineage-A Blob"),
            )
            .await
            .expect("recover exact lineage-A operation");
        assert!(!retry_a.inserted);
        assert_eq!(retry_a.publisher_counter, published_a.publisher_counter);
        assert_eq!(retry_a.acceptance_marker, published_a.acceptance_marker);

        let conflicting_a = blobs
            .publish(
                live_blob_request(
                    b"blob-lineage-a-under-replacement",
                    &services.topic,
                    &services.scope,
                ),
                File::open(&a_path).expect("reopen A under replacement lineage"),
            )
            .await
            .expect_err("same numeric epoch may not replace physical Blob lineage");
        assert_eq!(conflicting_a.kind(), ApplicationErrorKind::Conflict);
        assert_eq!(conflicting_a.operation(), "blob publish");

        let request_b = live_blob_request(b"blob-lineage-b", &services.topic, &services.scope);
        let published_b = blobs
            .publish(
                request_b.clone(),
                File::open(&b_path).expect("open lineage-B Blob"),
            )
            .await
            .expect("publish intermediate lineage-B Blob");
        assert!(published_b.inserted);

        let epoch_two = controls
            .publish_scope_rekey(
                ScopeRekeyRequest::new(
                    services.registry_next.clone(),
                    RegistryGenerationWitness::new(NonZeroU64::new(2).expect("nonzero")),
                    services.scope.clone(),
                    NonZeroU64::new(2).expect("nonzero"),
                    recipients,
                )
                .expect("epoch-two Blob rekey request"),
            )
            .await
            .expect("publish epoch-two Blob rekey");
        assert!(epoch_two.emitted);

        let retry_b = blobs
            .publish(
                request_b.clone(),
                File::open(&b_path).expect("reopen intermediate lineage-B Blob"),
            )
            .await
            .expect("recover intermediate lineage-B operation");
        assert!(!retry_b.inserted);
        assert_eq!(retry_b.publisher_counter, published_b.publisher_counter);
        assert_eq!(retry_b.acceptance_marker, published_b.acceptance_marker);
        let read_b = BlobReadRequest {
            id: published_b.id,
            topic: services.topic.clone(),
            scope: services.scope.clone(),
        };
        assert_eq!(
            blobs
                .read_page(BlobReadPageRequest {
                    blob: read_b.clone(),
                    offset: 0,
                    max_bytes: 1,
                })
                .await
                .expect_err("intermediate lineage remains withheld before replacement")
                .kind(),
            ApplicationErrorKind::UnauthorizedOrRevoked
        );

        let request_c = live_blob_request(b"blob-lineage-c", &services.topic, &services.scope);
        let published_c = blobs
            .publish(
                request_c,
                File::open(&b_path).expect("open lineage-C replacement Blob"),
            )
            .await
            .expect("epoch advance permits a new physical Blob lineage");
        assert!(published_c.inserted);
        assert_eq!(published_c.id, published_b.id);
        assert_eq!(read_live_blob_pages(&blobs, read_b.clone()).await, b_bytes);

        let receipt = running.shutdown().await.expect("shutdown Blob rekey actor");
        assert_eq!(receipt.controls, 2);
        assert_eq!(receipt.applied_controls, 2);
        assert_eq!(receipt.blobs, 3);
        assert_eq!(receipt.blob_acceptance_markers, 3);
        assert_eq!(receipt.blob_last_acceptance_marker, 3);
        assert_eq!(receipt.blob_operations, 3);
        assert_eq!(receipt.blob_variants, 3);
        assert_eq!(receipt.blob_finalized_variants, 3);
        assert_eq!(receipt.blob_committed_chunks, 6);

        {
            let store = Store::open_for_mission(
                state.join(STORE_FILE),
                restart_mission.mission_authority_id(),
            )
            .expect("open three-lineage Blob store for bounded startup proof");
            let startup = open_startup_event_verifier_and_cache(&store, &restart_mission)
                .expect("rebuild bounded three-lineage Blob cache");
            assert_eq!(startup.cache.blob_claim_count(), 3);
            assert_eq!(startup.cache.startup_blob_completion_audits(), 3);
            assert_eq!(
                startup.cache.startup_blob_replay_candidate_visits(),
                2,
                "incremental replay visits only B's same-epoch and C's next-epoch buckets"
            );
        }

        let reopened = start_node(config(restart_mission))
            .await
            .expect("restart three-lineage Blob actor");
        let reopened_blobs = reopened.selected_blobs();
        assert_eq!(
            read_live_blob_pages(&reopened_blobs, read_b).await,
            b_bytes,
            "restart must select only current lineage-C plaintext"
        );
        let restarted_b = reopened_blobs
            .publish(
                request_b,
                File::open(&b_path).expect("reopen intermediate B after restart"),
            )
            .await
            .expect("restart recovers intermediate provider operation");
        assert!(!restarted_b.inserted);
        assert_eq!(restarted_b.publisher_counter, published_b.publisher_counter);
        assert_eq!(restarted_b.acceptance_marker, published_b.acceptance_marker);
        let restarted_receipt = reopened
            .shutdown()
            .await
            .expect("shutdown restarted Blob actor");
        assert_eq!(restarted_receipt.blobs, receipt.blobs);
        assert_eq!(restarted_receipt.blob_operations, receipt.blob_operations);
        assert_eq!(restarted_receipt.blob_variants, receipt.blob_variants);
        assert_eq!(
            restarted_receipt.blob_committed_chunks,
            receipt.blob_committed_chunks
        );
        fs::remove_dir_all(root).expect("cleanup Blob rekey actor state");
    }

    #[tokio::test]
    async fn live_selected_blob_converges_over_direct_iroh_and_restarts_peerless() {
        use crate::application::{ApplicationErrorKind, BlobReadPageRequest, BlobReadRequest};

        let root = root("live-selected-blob-direct-iroh");
        let source_state = root.join("source");
        let receiver_state = root.join("receiver");
        let source_path = root.join("source.bin");
        fs::create_dir_all(&root).expect("direct-Iroh Blob root");
        let bytes = (0..(aster_mesh::SELECTED_BLOB_CHUNK_SIZE as usize + 211))
            .map(|index| (index.wrapping_mul(13) % 251) as u8)
            .collect::<Vec<_>>();
        fs::write(&source_path, &bytes).expect("direct-Iroh Blob source");
        let mut missions = issue_missions(2);
        let receiver_mission = missions.pop().expect("receiver mission");
        let source_mission = missions.pop().expect("source mission");
        let source_carrier = {
            let identity =
                NodeIdentity::load_or_create(&source_state).expect("source carrier identity");
            let id = identity.id();
            drop(identity);
            id
        };
        let receiver_carrier = {
            let identity =
                NodeIdentity::load_or_create(&receiver_state).expect("receiver carrier identity");
            let id = identity.id();
            drop(identity);
            id
        };
        let topic = Topic::new("opaque").expect("direct-Iroh Blob topic");
        let scope = Scope::new("test/runtime-contact").expect("direct-Iroh Blob scope");
        let request = live_blob_request(b"direct-iroh-blob", &topic, &scope);
        let offline = start_node(NodeConfig {
            state: source_state.clone(),
            bind: SocketAddr::from(([127, 0, 0, 1], 0)),
            mission: source_mission.credentials.clone(),
            peers: Vec::new(),
            mutable_interests: Default::default(),
            sync_interval: Duration::from_millis(10),
            run_for: None,
            application: NodeApplication::Relay,
        })
        .await
        .expect("start peerless direct-Iroh Blob source");
        let published = offline
            .selected_blobs()
            .publish(
                request,
                File::open(&source_path).expect("open direct-Iroh Blob source"),
            )
            .await
            .expect("live publish before direct-Iroh contact");
        assert!(published.inserted);
        offline
            .shutdown()
            .await
            .expect("stop peerless direct-Iroh Blob source");

        let source_socket = UdpSocket::bind(("127.0.0.1", 0)).expect("reserve source port");
        let receiver_socket = UdpSocket::bind(("127.0.0.1", 0)).expect("reserve receiver port");
        let source_address = source_socket.local_addr().expect("source address");
        let receiver_address = receiver_socket.local_addr().expect("receiver address");
        drop((source_socket, receiver_socket));
        let interests =
            MutableSourceInterests::default().with_blob(vec![SourceInterestSelector::new(
                topic.clone(),
                scope.clone(),
                false,
            )]);
        let source_config = NodeConfig {
            state: source_state.clone(),
            bind: source_address,
            mission: source_mission.credentials.clone(),
            peers: vec![MissionExpectedPeer {
                carrier: ExpectedPeer {
                    id: receiver_carrier,
                    address: receiver_address,
                },
                mission: receiver_mission.identity,
            }],
            mutable_interests: interests.clone(),
            sync_interval: Duration::from_millis(20),
            run_for: None,
            application: NodeApplication::Relay,
        };
        let receiver_config = NodeConfig {
            state: receiver_state.clone(),
            bind: receiver_address,
            mission: receiver_mission.credentials.clone(),
            peers: vec![MissionExpectedPeer {
                carrier: ExpectedPeer {
                    id: source_carrier,
                    address: source_address,
                },
                mission: source_mission.identity,
            }],
            mutable_interests: interests,
            sync_interval: Duration::from_millis(20),
            run_for: None,
            application: NodeApplication::Relay,
        };
        let (source_running, receiver_running) = if source_carrier > receiver_carrier {
            let source = start_node(source_config)
                .await
                .expect("start direct-Iroh source responder");
            let receiver = start_node(receiver_config)
                .await
                .expect("start direct-Iroh receiver initiator");
            (source, receiver)
        } else {
            let receiver = start_node(receiver_config)
                .await
                .expect("start direct-Iroh receiver responder");
            let source = start_node(source_config)
                .await
                .expect("start direct-Iroh source initiator");
            (source, receiver)
        };
        let receiver_blobs = receiver_running.selected_blobs();
        let read = BlobReadRequest {
            id: published.id,
            topic: topic.clone(),
            scope: scope.clone(),
        };
        timeout(Duration::from_secs(20), async {
            loop {
                match receiver_blobs
                    .read_page(BlobReadPageRequest {
                        blob: read.clone(),
                        offset: 0,
                        max_bytes: 1,
                    })
                    .await
                {
                    Ok(page) => {
                        assert_eq!(page.as_bytes(), &bytes[..1]);
                        break;
                    }
                    Err(error)
                        if matches!(
                            error.kind(),
                            ApplicationErrorKind::RequestRejected
                                | ApplicationErrorKind::UnauthorizedOrRevoked
                                | ApplicationErrorKind::PolicyUnsettled
                        ) =>
                    {
                        sleep(Duration::from_millis(20)).await;
                    }
                    Err(error) => panic!("direct-Iroh Blob read failed unexpectedly: {error}"),
                }
            }
        })
        .await
        .expect("direct-Iroh Blob convergence deadline");
        assert_eq!(
            read_live_blob_pages(&receiver_blobs, read.clone()).await,
            bytes
        );

        let source_status = source_running.selected_events();
        let receiver_status = receiver_running.selected_events();
        timeout(Duration::from_secs(20), async {
            loop {
                let source = source_status.status().await.expect("source contact status");
                let receiver = receiver_status
                    .status()
                    .await
                    .expect("receiver contact status");
                if source.authenticated_contacts > 0 && receiver.authenticated_contacts > 0 {
                    assert_eq!(source.failed_contact_attempts, 0);
                    assert_eq!(receiver.failed_contact_attempts, 0);
                    break;
                }
                sleep(Duration::from_millis(20)).await;
            }
        })
        .await
        .expect("direct-Iroh contact accounting deadline");
        let (source_receipt, receiver_receipt) =
            tokio::join!(source_running.shutdown(), receiver_running.shutdown());
        let source_receipt = source_receipt.expect("direct-Iroh source shutdown");
        let receiver_receipt = receiver_receipt.expect("direct-Iroh receiver shutdown");
        for receipt in [&source_receipt, &receiver_receipt] {
            assert!(receipt.contacts > 0);
            assert_eq!(receipt.contact_errors, 0);
            assert_eq!(receipt.direct_contacts, receipt.contacts);
            assert_eq!(receipt.relay_contacts, 0);
            assert_eq!(receipt.unknown_path_contacts, 0);
        }
        assert!(receiver_receipt.blob_ranges_fetched > 0);
        assert!(receiver_receipt.blob_bytes_fetched > 0);
        assert_eq!(receiver_receipt.blobs, 1);
        assert_eq!(receiver_receipt.blob_finalized_variants, 1);

        let reopened = start_node(NodeConfig {
            state: receiver_state,
            bind: SocketAddr::from(([127, 0, 0, 1], 0)),
            mission: receiver_mission.credentials,
            peers: Vec::new(),
            mutable_interests: Default::default(),
            sync_interval: Duration::from_millis(10),
            run_for: None,
            application: NodeApplication::Relay,
        })
        .await
        .expect("restart direct-Iroh receiver peerless");
        assert_eq!(
            read_live_blob_pages(&reopened.selected_blobs(), read).await,
            bytes
        );
        let restarted = reopened
            .shutdown()
            .await
            .expect("shutdown restarted direct-Iroh receiver");
        assert_eq!(restarted.blobs, receiver_receipt.blobs);
        assert_eq!(
            restarted.blob_committed_chunks,
            receiver_receipt.blob_committed_chunks
        );
        fs::remove_dir_all(root).expect("direct-Iroh Blob cleanup");
    }

    #[tokio::test]
    async fn live_selected_state_and_record_are_durable_idempotent_and_close_admission() {
        use crate::application::{
            ApplicationErrorKind, MAX_SELECTED_RECORD_DELIVERIES,
            MAX_SELECTED_RECORD_SUBSCRIPTION_SCAN, MAX_SELECTED_STATE_DELIVERIES,
            MAX_SELECTED_STATE_SUBSCRIPTION_SCAN, RecordAcknowledgement, RecordPollRequest,
            RecordPublishRequest, RecordQuery, RecordSubscriptionRequest, RecordUnsubscribe,
            StateAcknowledgement, StatePollRequest, StatePublishRequest, StateQuery,
            StateSubscriptionRequest, StateUnsubscribe,
        };

        let state = root("live-selected-mutable-actor");
        let scope = Scope::new("test/runtime").expect("scope");
        let topic = Topic::new("opaque").expect("topic");
        let state_key = b"live-state".to_vec();
        let record_key = b"live-record".to_vec();
        let mission = test_mission();
        let restart_mission = mission.clone();
        let running = start_node(NodeConfig {
            state: state.clone(),
            bind: SocketAddr::from(([127, 0, 0, 1], 0)),
            mission,
            peers: Vec::new(),
            mutable_interests: Default::default(),
            sync_interval: Duration::from_millis(10),
            run_for: None,
            application: NodeApplication::Relay,
        })
        .await
        .expect("start live selected mutable actor");
        let selected_state = running.selected_state();
        let selected_records = running.selected_records();
        assert_eq!(selected_state.identity(), selected_records.identity());
        assert_eq!(
            selected_state.mission_authority(),
            selected_records.mission_authority()
        );

        let state_request = StatePublishRequest {
            operation_key: b"runtime-live-state-publish".to_vec(),
            topic: topic.clone(),
            scope: scope.clone(),
            priority: Priority::Priority,
            logical_key: state_key.clone(),
            payload: b"live State payload".to_vec(),
            tombstone: false,
        };
        let published_state = selected_state
            .publish(state_request.clone())
            .await
            .expect("publish State while live");
        assert!(published_state.inserted);
        let retried_state = selected_state
            .publish(state_request.clone())
            .await
            .expect("retry exact live State publication");
        assert!(!retried_state.inserted);
        assert_eq!(retried_state.id, published_state.id);
        assert_eq!(
            retried_state.acceptance_marker,
            published_state.acceptance_marker
        );
        let mut conflicting_state = state_request;
        conflicting_state.payload = b"changed State payload".to_vec();
        assert_eq!(
            selected_state
                .publish(conflicting_state)
                .await
                .expect_err("changed State operation key must fail")
                .kind(),
            ApplicationErrorKind::Conflict
        );

        let record_request = RecordPublishRequest {
            operation_key: b"runtime-live-record-publish".to_vec(),
            topic: topic.clone(),
            scope: scope.clone(),
            priority: Priority::Priority,
            logical_key: record_key.clone(),
            payload: b"live Record payload".to_vec(),
            tombstone: false,
        };
        let published_record = selected_records
            .publish(record_request.clone())
            .await
            .expect("publish Record while live");
        assert!(published_record.inserted);
        let retried_record = selected_records
            .publish(record_request.clone())
            .await
            .expect("retry exact live Record publication");
        assert!(!retried_record.inserted);
        assert_eq!(retried_record.id, published_record.id);
        assert_eq!(
            retried_record.acceptance_marker,
            published_record.acceptance_marker
        );
        assert!(
            published_record.publisher_counter > published_state.publisher_counter,
            "State and Record publications share one causal frontier"
        );
        let mut conflicting_record = record_request;
        conflicting_record.payload = b"changed Record payload".to_vec();
        assert_eq!(
            selected_records
                .publish(conflicting_record)
                .await
                .expect_err("changed Record operation key must fail")
                .kind(),
            ApplicationErrorKind::Conflict
        );

        let state_query = StateQuery {
            topic: topic.clone(),
            scope: scope.clone(),
            logical_key: state_key,
            include_recoverable_versions: true,
        };
        let state_projection = selected_state
            .query(state_query.clone())
            .await
            .expect("query State while live");
        let current_state = state_projection.current.expect("current live State");
        assert_eq!(current_state.id, published_state.id);
        assert_eq!(current_state.payload, b"live State payload");
        assert!(state_projection.recoverable.is_empty());

        let state_subscription = selected_state
            .subscribe(StateSubscriptionRequest {
                operation_key: b"runtime-live-state-subscription".to_vec(),
                topic: state_query.topic.clone(),
                scope: state_query.scope.clone(),
                include_descendant_scopes: false,
            })
            .await
            .expect("subscribe to retained State while live");
        assert!(state_subscription.inserted);
        let state_delivery = selected_state
            .poll(StatePollRequest {
                subscription: state_subscription.id,
                delivery_limit: MAX_SELECTED_STATE_DELIVERIES,
                scan_limit: MAX_SELECTED_STATE_SUBSCRIPTION_SCAN,
            })
            .await
            .expect("poll State through live actor");
        assert_eq!(state_delivery.deliveries.len(), 1);
        assert_eq!(state_delivery.deliveries[0].state.id, published_state.id);
        assert_eq!(state_delivery.deliveries[0].attempt, 1);
        let state_delivery_token = state_delivery.deliveries[0].token;
        assert_eq!(
            selected_state
                .acknowledge(
                    state_subscription.id,
                    published_state.id,
                    state_delivery_token,
                )
                .await
                .expect("acknowledge State through live actor"),
            StateAcknowledgement::Acknowledged
        );
        assert_eq!(
            selected_state
                .acknowledge(
                    state_subscription.id,
                    published_state.id,
                    state_delivery_token,
                )
                .await
                .expect("repeat State acknowledgement through live actor"),
            StateAcknowledgement::AlreadyAcknowledged
        );

        let record_query = RecordQuery {
            topic,
            scope,
            logical_key: record_key,
            include_superseded_versions: true,
        };
        let record_projection = selected_records
            .query(record_query.clone())
            .await
            .expect("query Record while live");
        let current_record = record_projection.current.expect("current live Record");
        assert_eq!(current_record.id, published_record.id);
        assert_eq!(current_record.payload, b"live Record payload");
        assert!(record_projection.concurrent.is_empty());
        assert!(record_projection.superseded.is_empty());
        assert!(record_projection.conflict.is_none());

        let record_subscription = selected_records
            .subscribe(RecordSubscriptionRequest {
                operation_key: b"runtime-live-record-subscription".to_vec(),
                topic: record_query.topic.clone(),
                scope: record_query.scope.clone(),
                include_descendant_scopes: false,
            })
            .await
            .expect("subscribe to retained Record while live");
        assert!(record_subscription.inserted);
        let record_delivery = selected_records
            .poll(RecordPollRequest {
                subscription: record_subscription.id,
                delivery_limit: MAX_SELECTED_RECORD_DELIVERIES,
                scan_limit: MAX_SELECTED_RECORD_SUBSCRIPTION_SCAN,
            })
            .await
            .expect("poll Record through live actor");
        assert_eq!(record_delivery.deliveries.len(), 1);
        assert_eq!(
            record_delivery.deliveries[0]
                .projection
                .current
                .as_ref()
                .map(|item| item.id),
            Some(published_record.id)
        );
        assert!(
            record_delivery.deliveries[0]
                .projection
                .concurrent
                .is_empty()
        );
        assert!(record_delivery.deliveries[0].projection.conflict.is_none());
        assert_eq!(record_delivery.deliveries[0].attempt, 1);
        let record_projection_id = record_delivery.deliveries[0].projection_id;
        let record_delivery_token = record_delivery.deliveries[0].token;
        assert_eq!(
            selected_records
                .acknowledge(
                    record_subscription.id,
                    record_projection_id,
                    record_delivery_token,
                )
                .await
                .expect("acknowledge Record through live actor"),
            RecordAcknowledgement::Acknowledged
        );
        assert_eq!(
            selected_records
                .acknowledge(
                    record_subscription.id,
                    record_projection_id,
                    record_delivery_token,
                )
                .await
                .expect("repeat Record acknowledgement through live actor"),
            RecordAcknowledgement::AlreadyAcknowledged
        );

        let retained_state = selected_state.clone();
        let retained_records = selected_records.clone();
        let receipt = running.shutdown().await.expect("graceful mutable shutdown");
        assert_eq!(receipt.contacts, 0);
        assert_eq!(receipt.contact_errors, 0);
        let state_closed = retained_state
            .query(state_query.clone())
            .await
            .expect_err("closed actor rejects retained State handle");
        assert_eq!(state_closed.kind(), ApplicationErrorKind::StateUnavailable);
        assert_eq!(state_closed.operation(), "state query");
        let state_poll_closed = retained_state
            .poll(StatePollRequest {
                subscription: state_subscription.id,
                delivery_limit: MAX_SELECTED_STATE_DELIVERIES,
                scan_limit: MAX_SELECTED_STATE_SUBSCRIPTION_SCAN,
            })
            .await
            .expect_err("closed actor rejects retained State subscription handle");
        assert_eq!(
            state_poll_closed.kind(),
            ApplicationErrorKind::StateUnavailable
        );
        assert_eq!(state_poll_closed.operation(), "state poll");
        let record_closed = retained_records
            .query(record_query.clone())
            .await
            .expect_err("closed actor rejects retained Record handle");
        assert_eq!(record_closed.kind(), ApplicationErrorKind::StateUnavailable);
        assert_eq!(record_closed.operation(), "record query");
        let record_poll_closed = retained_records
            .poll(RecordPollRequest {
                subscription: record_subscription.id,
                delivery_limit: MAX_SELECTED_RECORD_DELIVERIES,
                scan_limit: MAX_SELECTED_RECORD_SUBSCRIPTION_SCAN,
            })
            .await
            .expect_err("closed actor rejects retained Record subscription handle");
        assert_eq!(
            record_poll_closed.kind(),
            ApplicationErrorKind::StateUnavailable
        );
        assert_eq!(record_poll_closed.operation(), "record poll");

        let reopened = start_node(NodeConfig {
            state: state.clone(),
            bind: SocketAddr::from(([127, 0, 0, 1], 0)),
            mission: restart_mission,
            peers: Vec::new(),
            mutable_interests: Default::default(),
            sync_interval: Duration::from_millis(10),
            run_for: None,
            application: NodeApplication::Relay,
        })
        .await
        .expect("restart live selected mutable actor");
        assert_eq!(
            reopened
                .selected_state()
                .query(state_query)
                .await
                .expect("query State after restart")
                .current
                .expect("retained State after restart")
                .id,
            published_state.id
        );
        let reopened_state_handle = reopened.selected_state();
        assert!(
            reopened_state_handle
                .poll(StatePollRequest {
                    subscription: state_subscription.id,
                    delivery_limit: MAX_SELECTED_STATE_DELIVERIES,
                    scan_limit: MAX_SELECTED_STATE_SUBSCRIPTION_SCAN,
                })
                .await
                .expect("acknowledged State subscription survives restart")
                .deliveries
                .is_empty()
        );
        assert_eq!(
            reopened_state_handle
                .unsubscribe(state_subscription.id)
                .await
                .expect("unsubscribe State through live actor"),
            StateUnsubscribe::Removed
        );
        assert_eq!(
            reopened_state_handle
                .unsubscribe(state_subscription.id)
                .await
                .expect("repeat State unsubscribe through live actor"),
            StateUnsubscribe::AlreadyAbsent
        );
        let reopened_record_handle = reopened.selected_records();
        assert_eq!(
            reopened_record_handle
                .query(record_query)
                .await
                .expect("query Record after restart")
                .current
                .expect("retained Record after restart")
                .id,
            published_record.id
        );
        assert!(
            reopened_record_handle
                .poll(RecordPollRequest {
                    subscription: record_subscription.id,
                    delivery_limit: MAX_SELECTED_RECORD_DELIVERIES,
                    scan_limit: MAX_SELECTED_RECORD_SUBSCRIPTION_SCAN,
                })
                .await
                .expect("acknowledged Record subscription survives restart")
                .deliveries
                .is_empty()
        );
        assert_eq!(
            reopened_record_handle
                .unsubscribe(record_subscription.id)
                .await
                .expect("unsubscribe Record through live actor"),
            RecordUnsubscribe::Removed
        );
        assert_eq!(
            reopened_record_handle
                .unsubscribe(record_subscription.id)
                .await
                .expect("repeat Record unsubscribe through live actor"),
            RecordUnsubscribe::AlreadyAbsent
        );
        reopened.shutdown().await.expect("shutdown reopened actor");
        fs::remove_dir_all(state).expect("cleanup live mutable actor state");
    }

    #[tokio::test]
    async fn live_mutable_handles_converge_disconnected_state_and_record_then_resolve() {
        use crate::application::{
            ApplicationErrorKind, RecordPublishRequest, RecordQuery, RecordResolveRequest,
            RecordVersionDisposition, StatePublishRequest, StateQuery, StateVersionDisposition,
        };

        let root = root("live-mutable-disconnected-convergence");
        let left_state = root.join("left");
        let right_state = root.join("right");
        let mut issued = issue_missions(2);
        let right_mission = issued.pop().expect("right mission");
        let left_mission = issued.pop().expect("left mission");
        let left_carrier = {
            let identity =
                NodeIdentity::load_or_create(&left_state).expect("left carrier identity");
            let id = identity.id();
            drop(identity);
            id
        };
        let right_carrier = {
            let identity =
                NodeIdentity::load_or_create(&right_state).expect("right carrier identity");
            let id = identity.id();
            drop(identity);
            id
        };
        let scope = Scope::new("test/runtime-contact").expect("scope");
        let topic = Topic::new("opaque").expect("topic");
        let state_key = b"disconnected-state".to_vec();
        let record_key = b"disconnected-record".to_vec();

        let left_offline = start_node(NodeConfig {
            state: left_state.clone(),
            bind: SocketAddr::from(([127, 0, 0, 1], 0)),
            mission: left_mission.credentials.clone(),
            peers: Vec::new(),
            mutable_interests: Default::default(),
            sync_interval: Duration::from_millis(10),
            run_for: None,
            application: NodeApplication::Relay,
        })
        .await
        .expect("start disconnected left node");
        let right_offline = start_node(NodeConfig {
            state: right_state.clone(),
            bind: SocketAddr::from(([127, 0, 0, 1], 0)),
            mission: right_mission.credentials.clone(),
            peers: Vec::new(),
            mutable_interests: Default::default(),
            sync_interval: Duration::from_millis(10),
            run_for: None,
            application: NodeApplication::Relay,
        })
        .await
        .expect("start disconnected right node");

        let left_state_publication = left_offline
            .selected_state()
            .publish(StatePublishRequest {
                operation_key: b"left-disconnected-state".to_vec(),
                topic: topic.clone(),
                scope: scope.clone(),
                priority: Priority::Priority,
                logical_key: state_key.clone(),
                payload: b"left State".to_vec(),
                tombstone: false,
            })
            .await
            .expect("publish left disconnected State");
        let right_state_publication = right_offline
            .selected_state()
            .publish(StatePublishRequest {
                operation_key: b"right-disconnected-state".to_vec(),
                topic: topic.clone(),
                scope: scope.clone(),
                priority: Priority::Priority,
                logical_key: state_key.clone(),
                payload: b"right State".to_vec(),
                tombstone: false,
            })
            .await
            .expect("publish right disconnected State");
        assert_ne!(left_state_publication.id, right_state_publication.id);

        let left_record_publication = left_offline
            .selected_records()
            .publish(RecordPublishRequest {
                operation_key: b"left-disconnected-record".to_vec(),
                topic: topic.clone(),
                scope: scope.clone(),
                priority: Priority::Priority,
                logical_key: record_key.clone(),
                payload: b"left Record".to_vec(),
                tombstone: false,
            })
            .await
            .expect("publish left disconnected Record");
        let right_record_publication = right_offline
            .selected_records()
            .publish(RecordPublishRequest {
                operation_key: b"right-disconnected-record".to_vec(),
                topic: topic.clone(),
                scope: scope.clone(),
                priority: Priority::Priority,
                logical_key: record_key.clone(),
                payload: b"right Record".to_vec(),
                tombstone: false,
            })
            .await
            .expect("publish right disconnected Record");
        assert_ne!(left_record_publication.id, right_record_publication.id);
        let expected_current_state = left_state_publication.id.max(right_state_publication.id);
        let expected_concurrent_state = left_state_publication.id.min(right_state_publication.id);
        let (left_offline_receipt, right_offline_receipt) =
            tokio::join!(left_offline.shutdown(), right_offline.shutdown());
        assert_eq!(
            left_offline_receipt
                .expect("left offline shutdown")
                .contacts,
            0
        );
        assert_eq!(
            right_offline_receipt
                .expect("right offline shutdown")
                .contacts,
            0
        );

        let left_port = UdpSocket::bind(("127.0.0.1", 0)).expect("reserve left mutable port");
        let right_port = UdpSocket::bind(("127.0.0.1", 0)).expect("reserve right mutable port");
        let left_address = left_port.local_addr().expect("left mutable address");
        let right_address = right_port.local_addr().expect("right mutable address");
        drop((left_port, right_port));
        let interests = MutableSourceInterests::new(
            vec![SourceInterestSelector::new(
                topic.clone(),
                scope.clone(),
                false,
            )],
            vec![SourceInterestSelector::new(
                topic.clone(),
                scope.clone(),
                false,
            )],
        );
        let left_config = NodeConfig {
            state: left_state.clone(),
            bind: left_address,
            mission: left_mission.credentials.clone(),
            peers: vec![MissionExpectedPeer {
                carrier: ExpectedPeer {
                    id: right_carrier,
                    address: right_address,
                },
                mission: right_mission.identity,
            }],
            mutable_interests: interests.clone(),
            sync_interval: Duration::from_millis(20),
            run_for: None,
            application: NodeApplication::Relay,
        };
        let right_config = NodeConfig {
            state: right_state.clone(),
            bind: right_address,
            mission: right_mission.credentials.clone(),
            peers: vec![MissionExpectedPeer {
                carrier: ExpectedPeer {
                    id: left_carrier,
                    address: left_address,
                },
                mission: left_mission.identity,
            }],
            mutable_interests: interests,
            sync_interval: Duration::from_millis(20),
            run_for: None,
            application: NodeApplication::Relay,
        };
        // The lower carrier identity is the sole initiator. Start the higher
        // identity first so no expected startup absence becomes a failed
        // authenticated-contact attempt.
        let (left_running, right_running) = if left_carrier > right_carrier {
            let left = start_node(left_config)
                .await
                .expect("restart connected left responder");
            let right = start_node(right_config)
                .await
                .expect("restart connected right initiator");
            (left, right)
        } else {
            let right = start_node(right_config)
                .await
                .expect("restart connected right responder");
            let left = start_node(left_config)
                .await
                .expect("restart connected left initiator");
            (left, right)
        };
        let left_state_handle = left_running.selected_state();
        let right_state_handle = right_running.selected_state();
        let left_records = left_running.selected_records();
        let right_records = right_running.selected_records();
        let left_status = left_running.selected_events();
        let right_status = right_running.selected_events();
        let state_query = StateQuery {
            topic: topic.clone(),
            scope: scope.clone(),
            logical_key: state_key,
            include_recoverable_versions: true,
        };
        let record_query = RecordQuery {
            topic,
            scope,
            logical_key: record_key,
            include_superseded_versions: true,
        };

        let (left_record_projection, right_record_projection) =
            timeout(Duration::from_secs(20), async {
                loop {
                    let left_state_projection = left_state_handle
                        .query(state_query.clone())
                        .await
                        .expect("live left State query");
                    let right_state_projection = right_state_handle
                        .query(state_query.clone())
                        .await
                        .expect("live right State query");
                    let left_record_projection = left_records
                        .query(record_query.clone())
                        .await
                        .expect("live left Record query");
                    let right_record_projection = right_records
                        .query(record_query.clone())
                        .await
                        .expect("live right Record query");
                    let state_converged =
                        left_state_projection.current.as_ref().is_some_and(|item| {
                            item.id == expected_current_state
                                && item.disposition == StateVersionDisposition::Current
                        }) && right_state_projection.current.as_ref().is_some_and(|item| {
                            item.id == expected_current_state
                                && item.disposition == StateVersionDisposition::Current
                        }) && left_state_projection.recoverable.len() == 1
                            && right_state_projection.recoverable.len() == 1
                            && left_state_projection.recoverable[0].id == expected_concurrent_state
                            && right_state_projection.recoverable[0].id
                                == expected_concurrent_state
                            && left_state_projection.recoverable[0].disposition
                                == StateVersionDisposition::Concurrent
                            && right_state_projection.recoverable[0].disposition
                                == StateVersionDisposition::Concurrent;
                    let records_converged = left_record_projection
                        .conflict
                        .as_ref()
                        .zip(right_record_projection.conflict.as_ref())
                        .is_some_and(|(left, right)| {
                            left.siblings == right.siblings && left.siblings.len() == 2
                        });
                    if state_converged && records_converged {
                        break (left_record_projection, right_record_projection);
                    }
                    sleep(Duration::from_millis(20)).await;
                }
            })
            .await
            .expect("live State and Record projections converge");
        timeout(Duration::from_secs(20), async {
            loop {
                let left = left_status
                    .status()
                    .await
                    .expect("left initial contact status");
                let right = right_status
                    .status()
                    .await
                    .expect("right initial contact status");
                assert_eq!(left.failed_contact_attempts, 0);
                assert_eq!(right.failed_contact_attempts, 0);
                if left.authenticated_contacts > 0 && right.authenticated_contacts > 0 {
                    break;
                }
                sleep(Duration::from_millis(20)).await;
            }
        })
        .await
        .expect("initial contact accounting completes");
        assert_eq!(
            left_record_projection
                .conflict
                .as_ref()
                .expect("left conflict")
                .siblings,
            vec![left_record_publication.id, right_record_publication.id]
                .into_iter()
                .collect::<BTreeSet<_>>()
                .into_iter()
                .collect::<Vec<_>>()
        );
        assert_eq!(
            right_record_projection
                .conflict
                .as_ref()
                .expect("right conflict")
                .siblings,
            left_record_projection
                .conflict
                .as_ref()
                .expect("left conflict")
                .siblings
        );

        let expected_siblings = left_record_projection
            .conflict
            .as_ref()
            .expect("left conflict before ordinary publication")
            .siblings
            .clone();
        let expected_sibling_set = expected_siblings.iter().copied().collect::<BTreeSet<_>>();
        let ordinary_conflict = left_records
            .publish(RecordPublishRequest {
                operation_key: b"ordinary-publish-cannot-hide-conflict".to_vec(),
                topic: record_query.topic.clone(),
                scope: record_query.scope.clone(),
                priority: Priority::Priority,
                logical_key: record_query.logical_key.clone(),
                payload: b"must not replace disconnected siblings".to_vec(),
                tombstone: false,
            })
            .await
            .expect_err("ordinary Record publication must not hide a conflict");
        assert_eq!(ordinary_conflict.kind(), ApplicationErrorKind::Conflict);
        assert_eq!(ordinary_conflict.operation(), "record publish");
        assert_eq!(
            left_records
                .query(record_query.clone())
                .await
                .expect("conflict remains after rejected ordinary publication")
                .conflict
                .expect("preserved conflict")
                .siblings,
            expected_siblings
        );

        let resolution = RecordResolveRequest {
            operation_key: b"resolve-disconnected-record".to_vec(),
            resolution_guard: left_record_projection
                .conflict
                .expect("left resolution guard")
                .resolution_guard,
            priority: Priority::Immediate,
            payload: b"resolved Record".to_vec(),
            tombstone: false,
        };
        let restart_resolution = resolution.clone();
        let resolved = left_records
            .resolve(resolution.clone())
            .await
            .expect("resolve live Record conflict");
        assert!(resolved.inserted);
        let retry = left_records
            .resolve(resolution)
            .await
            .expect("retry exact live Record resolution");
        assert!(!retry.inserted);
        assert_eq!(retry.id, resolved.id);
        let left_contact_baseline = left_status
            .status()
            .await
            .expect("left contact baseline")
            .authenticated_contacts;
        let right_contact_baseline = right_status
            .status()
            .await
            .expect("right contact baseline")
            .authenticated_contacts;

        timeout(Duration::from_secs(20), async {
            loop {
                let left = left_records
                    .query(record_query.clone())
                    .await
                    .expect("left resolved Record query");
                let right = right_records
                    .query(record_query.clone())
                    .await
                    .expect("right resolved Record query");
                if left
                    .current
                    .as_ref()
                    .is_some_and(|item| item.id == resolved.id)
                    && right
                        .current
                        .as_ref()
                        .is_some_and(|item| item.id == resolved.id)
                    && left.conflict.is_none()
                    && right.conflict.is_none()
                    && left.superseded.len() == 2
                    && right.superseded.len() == 2
                {
                    break;
                }
                sleep(Duration::from_millis(20)).await;
            }
        })
        .await
        .expect("live Record resolution converges");

        timeout(Duration::from_secs(20), async {
            loop {
                let left = left_status.status().await.expect("left contact status");
                let right = right_status.status().await.expect("right contact status");
                assert_eq!(left.failed_contact_attempts, 0);
                assert_eq!(right.failed_contact_attempts, 0);
                if left.authenticated_contacts > left_contact_baseline
                    && right.authenticated_contacts > right_contact_baseline
                {
                    break;
                }
                sleep(Duration::from_millis(20)).await;
            }
        })
        .await
        .expect("post-resolution contact accounting completes");

        let (left_receipt, right_receipt) =
            tokio::join!(left_running.shutdown(), right_running.shutdown());
        let left_receipt = left_receipt.expect("left connected shutdown");
        let right_receipt = right_receipt.expect("right connected shutdown");
        assert!(
            u64::try_from(left_receipt.contacts).expect("left contacts fit u64")
                > left_contact_baseline
        );
        assert!(
            u64::try_from(right_receipt.contacts).expect("right contacts fit u64")
                > right_contact_baseline
        );
        for receipt in [&left_receipt, &right_receipt] {
            assert!(receipt.contacts > 0);
            assert_eq!(receipt.direct_contacts, receipt.contacts);
            assert_eq!(receipt.relay_contacts, 0);
            assert_eq!(receipt.unknown_path_contacts, 0);
            assert_eq!(receipt.contact_errors, 0);
        }

        let left_reopened = start_node(NodeConfig {
            state: left_state,
            bind: SocketAddr::from(([127, 0, 0, 1], 0)),
            mission: left_mission.credentials,
            peers: Vec::new(),
            mutable_interests: Default::default(),
            sync_interval: Duration::from_millis(10),
            run_for: None,
            application: NodeApplication::Relay,
        })
        .await
        .expect("reopen resolved left node");
        let right_reopened = start_node(NodeConfig {
            state: right_state,
            bind: SocketAddr::from(([127, 0, 0, 1], 0)),
            mission: right_mission.credentials,
            peers: Vec::new(),
            mutable_interests: Default::default(),
            sync_interval: Duration::from_millis(10),
            run_for: None,
            application: NodeApplication::Relay,
        })
        .await
        .expect("reopen resolved right node");
        let left_reopened_records = left_reopened.selected_records();
        for projection in [
            left_reopened
                .selected_state()
                .query(state_query.clone())
                .await
                .expect("left converged State after restart"),
            right_reopened
                .selected_state()
                .query(state_query)
                .await
                .expect("right converged State after restart"),
        ] {
            let current = projection.current.expect("current State after restart");
            assert_eq!(current.id, expected_current_state);
            assert_eq!(current.disposition, StateVersionDisposition::Current);
            assert_eq!(projection.recoverable.len(), 1);
            assert_eq!(projection.recoverable[0].id, expected_concurrent_state);
            assert_eq!(
                projection.recoverable[0].disposition,
                StateVersionDisposition::Concurrent
            );
        }
        for projection in [
            left_reopened_records
                .query(record_query.clone())
                .await
                .expect("left resolved projection after restart"),
            right_reopened
                .selected_records()
                .query(record_query)
                .await
                .expect("right resolved projection after restart"),
        ] {
            assert_eq!(
                projection
                    .current
                    .as_ref()
                    .expect("resolved current after restart")
                    .id,
                resolved.id
            );
            assert!(projection.conflict.is_none());
            assert_eq!(projection.superseded.len(), 2);
            assert!(
                projection
                    .superseded
                    .iter()
                    .all(|item| item.disposition == RecordVersionDisposition::Superseded)
            );
            assert_eq!(
                projection
                    .superseded
                    .iter()
                    .map(|item| item.id)
                    .collect::<BTreeSet<_>>(),
                expected_sibling_set
            );
        }
        let restarted_retry = left_reopened_records
            .resolve(restart_resolution.clone())
            .await
            .expect("retry exact resolution after restart");
        assert!(!restarted_retry.inserted);
        assert_eq!(restarted_retry.id, resolved.id);
        let (left_reopened_receipt, right_reopened_receipt) =
            tokio::join!(left_reopened.shutdown(), right_reopened.shutdown());
        assert_eq!(
            left_reopened_receipt
                .expect("left reopened shutdown")
                .contacts,
            0
        );
        assert_eq!(
            right_reopened_receipt
                .expect("right reopened shutdown")
                .contacts,
            0
        );
        let closed_resolution = left_reopened_records
            .resolve(restart_resolution)
            .await
            .expect_err("retained Record handle closes after restart shutdown");
        assert_eq!(
            closed_resolution.kind(),
            ApplicationErrorKind::StateUnavailable
        );
        assert_eq!(closed_resolution.operation(), "record resolve");
        fs::remove_dir_all(root).expect("cleanup live mutable convergence state");
    }

    fn demo_member_mission() -> UnprotectedReferenceMission {
        let access = ProvisioningAccess::member(
            demo_scope().expect("demo scope"),
            vec![1],
            vec![demo_event_topic().expect("demo topic")],
        )
        .expect("demo member access");
        let mut provisioner =
            ReferenceProvisioner::from_seed([0x94; 32]).expect("demo test provisioner");
        let bundle = provisioner
            .issue_node(1, &[access])
            .expect("issue demo member");
        UnprotectedReferenceMission::from_bytes(bundle.to_bytes().expect("encode demo bundle"))
            .expect("parse demo member")
    }

    struct ControlTestServices {
        authority: UnprotectedReferenceMission,
        member: UnprotectedReferenceMission,
        other: UnprotectedReferenceMission,
        excluded: UnprotectedReferenceMission,
        registry: Vec<u8>,
        registry_next: Vec<u8>,
        scope: Scope,
        topic: Topic,
    }

    fn control_test_services(seed: [u8; 32]) -> ControlTestServices {
        control_test_services_with_additional_scope(seed, None)
    }

    fn control_test_services_with_additional_scope(
        seed: [u8; 32],
        additional_scope: Option<Scope>,
    ) -> ControlTestServices {
        let scope = Scope::new("test/selected-control").expect("control scope");
        let topic = Topic::new("control-event").expect("control topic");
        let access = ProvisioningAccess::member(scope.clone(), vec![1], vec![topic.clone()])
            .expect("control access");
        let mut accesses = vec![access];
        if let Some(additional_scope) = additional_scope {
            accesses.push(
                ProvisioningAccess::member(additional_scope, vec![1], vec![topic.clone()])
                    .expect("additional control-test access"),
            );
        }
        let mut provisioner = ReferenceProvisioner::from_seed(seed).expect("control provisioner");
        let authority_bytes = provisioner
            .issue_control_authority(1, &accesses)
            .expect("issue authority")
            .to_bytes()
            .expect("encode authority");
        let authority = UnprotectedReferenceMission::from_bytes(authority_bytes)
            .expect("parse authority mission");
        let member_bytes = provisioner
            .issue_node(2, &accesses)
            .expect("issue member")
            .to_bytes()
            .expect("encode member");
        let member =
            UnprotectedReferenceMission::from_bytes(member_bytes).expect("parse member mission");
        let other_bytes = provisioner
            .issue_node(3, &accesses)
            .expect("issue other")
            .to_bytes()
            .expect("encode other");
        let other =
            UnprotectedReferenceMission::from_bytes(other_bytes).expect("parse other mission");
        let registry = provisioner
            .export_rekey_registry()
            .expect("signed registry");
        let excluded_bytes = provisioner
            .issue_node(4, &accesses)
            .expect("issue excluded registry member")
            .to_bytes()
            .expect("encode excluded");
        let excluded = UnprotectedReferenceMission::from_bytes(excluded_bytes)
            .expect("parse excluded mission");
        let registry_next = provisioner
            .export_rekey_registry()
            .expect("next signed registry");
        ControlTestServices {
            authority,
            member,
            other,
            excluded,
            registry,
            registry_next,
            scope,
            topic,
        }
    }

    fn open_test_sealer(mission: &UnprotectedReferenceMission) -> ReferenceEnvelopeSealer {
        ReferenceEnvelopeSealer::open(mission.fresh_bundle().expect("fresh test bundle"))
            .expect("open test sealer")
    }

    struct RuntimeTestUnprotector {
        calls: usize,
        plaintext: Option<Vec<u8>>,
    }

    impl ProvisioningUnprotector for RuntimeTestUnprotector {
        fn unprotect(
            &mut self,
            _protected: &[u8],
            _max_plaintext_len: usize,
        ) -> Result<UnprotectedProvisioning, ProvisioningProtectionError> {
            self.calls += 1;
            UnprotectedProvisioning::new(
                self.plaintext
                    .take()
                    .expect("test protection provider is called once"),
            )
        }
    }

    #[tokio::test]
    async fn protected_live_controls_refresh_policy_retry_exactly_and_close_on_shutdown() {
        use std::num::NonZeroU64;

        use crate::{
            application::{ApplicationErrorKind, EventPublishRequest},
            control_admin::{
                ControlAdminErrorKind, RegistryGenerationWitness, RevocationRequest,
                ScopeRekeyRequest,
            },
        };

        let state = root("protected-live-controls");
        let services = control_test_services([0xc8; 32]);
        let authority_bytes = services
            .authority
            .fresh_bundle()
            .expect("authority bundle")
            .to_bytes()
            .expect("encode authority bundle");
        let mut provider = RuntimeTestUnprotector {
            calls: 0,
            plaintext: Some(authority_bytes),
        };
        let config = NodeConfig::from_protected_bytes(
            &state,
            b"provider-authenticated-runtime-envelope",
            NodeConfigOptions::new(
                SocketAddr::from(([127, 0, 0, 1], 0)),
                Duration::from_secs(60),
            ),
            &mut provider,
        )
        .expect("construct protected runtime config");
        assert_eq!(provider.calls, 1);
        assert_eq!(
            config.provisioning_origin(),
            MissionProvisioningOrigin::ProtectedArtifact
        );
        assert!(!state.exists(), "bootstrap must not create durable state");

        let running = start_node(config)
            .await
            .expect("start protected authority runtime");
        let controls = running.selected_controls();
        let events = running.selected_events();
        assert_eq!(controls.identity(), services.authority.identity());
        assert_eq!(
            controls.mission_authority(),
            services.authority.mission_authority_id()
        );

        let recipients = vec![
            ScopeRekeyRecipient::member(
                services.authority.identity(),
                vec![services.topic.clone()],
            )
            .expect("authority recipient"),
            ScopeRekeyRecipient::member(services.member.identity(), vec![services.topic.clone()])
                .expect("member recipient"),
        ];
        let rekey = controls
            .publish_scope_rekey(
                ScopeRekeyRequest::new(
                    services.registry.clone(),
                    RegistryGenerationWitness::new(NonZeroU64::new(1).expect("nonzero")),
                    services.scope.clone(),
                    NonZeroU64::new(2).expect("nonzero"),
                    recipients.clone(),
                )
                .expect("bounded rekey request"),
            )
            .await
            .expect("publish live rekey");
        assert!(rekey.emitted);
        assert_eq!(rekey.activated, 1);

        let mut reversed = recipients;
        reversed.reverse();
        let exact_rekey = controls
            .publish_scope_rekey(
                ScopeRekeyRequest::new(
                    services.registry.clone(),
                    RegistryGenerationWitness::new(NonZeroU64::new(u64::MAX).expect("nonzero")),
                    services.scope.clone(),
                    NonZeroU64::new(2).expect("nonzero"),
                    reversed,
                )
                .expect("exact retry request"),
            )
            .await
            .expect("exact live rekey retry");
        assert!(!exact_rekey.emitted);
        assert_eq!(exact_rekey.transfer_id, rekey.transfer_id);
        assert_eq!(exact_rekey.sequence, rekey.sequence);

        let published = events
            .publish(EventPublishRequest {
                operation_key: b"post-live-rekey-publish".to_vec(),
                predecessor: None,
                topic: services.topic.clone(),
                scope: services.scope.clone(),
                priority: Priority::Immediate,
                logical_key: b"live-control-policy-refresh".to_vec(),
                payload: b"epoch two application bytes".to_vec(),
                tombstone: false,
            })
            .await
            .expect("application verifier observes live rekey before response");
        assert!(published.inserted);

        let revoke_request = RevocationRequest::new(
            services.other.identity(),
            NonZeroU64::new(1).expect("nonzero"),
        );
        let revocation = controls
            .publish_revocation(revoke_request)
            .await
            .expect("publish live revocation");
        assert!(revocation.emitted);
        let exact_revocation = controls
            .publish_revocation(revoke_request)
            .await
            .expect("exact revocation retry");
        assert!(!exact_revocation.emitted);
        assert_eq!(exact_revocation.transfer_id, revocation.transfer_id);

        let retained_controls = controls.clone();
        let retained_events = events.clone();
        let receipt = running
            .shutdown()
            .await
            .expect("graceful protected shutdown");
        assert_eq!(receipt.events, 1);
        assert_eq!(receipt.controls, 2);
        assert_eq!(receipt.applied_controls, 2);
        assert_eq!(
            retained_controls
                .publish_revocation(RevocationRequest::new(
                    services.excluded.identity(),
                    NonZeroU64::new(1).expect("nonzero"),
                ))
                .await
                .expect_err("closed actor rejects retained control handle")
                .kind(),
            ControlAdminErrorKind::StateUnavailable
        );
        assert_eq!(
            retained_events
                .status()
                .await
                .expect_err("closed actor rejects retained Event handle")
                .kind(),
            ApplicationErrorKind::StateUnavailable
        );
        fs::remove_dir_all(state).expect("cleanup protected live state");
    }

    #[tokio::test]
    async fn protected_live_mutable_handles_cache_exact_retry_across_same_epoch_rekey() {
        use std::num::NonZeroU64;

        use crate::{
            application::{RecordPublishRequest, RecordQuery, StatePublishRequest, StateQuery},
            control_admin::{RegistryGenerationWitness, ScopeRekeyRequest},
        };

        let state = root("protected-live-mutable-same-epoch-rekey");
        let services = control_test_services([0xd8; 32]);
        let protected_config = |plaintext: Vec<u8>| {
            let mut provider = RuntimeTestUnprotector {
                calls: 0,
                plaintext: Some(plaintext),
            };
            let config = NodeConfig::from_protected_bytes(
                &state,
                b"provider-authenticated-live-mutable-envelope",
                NodeConfigOptions::new(
                    SocketAddr::from(([127, 0, 0, 1], 0)),
                    Duration::from_secs(60),
                ),
                &mut provider,
            )
            .expect("construct protected mutable runtime config");
            assert_eq!(provider.calls, 1);
            config
        };
        let authority_bytes = services
            .authority
            .fresh_bundle()
            .expect("authority bundle")
            .to_bytes()
            .expect("encode authority bundle");
        let running = start_node(protected_config(authority_bytes))
            .await
            .expect("start protected mutable authority");
        let state_handle = running.selected_state();
        let records = running.selected_records();
        let controls = running.selected_controls();
        let state_query = StateQuery {
            topic: services.topic.clone(),
            scope: services.scope.clone(),
            logical_key: b"same-epoch-state".to_vec(),
            include_recoverable_versions: true,
        };
        let record_query = RecordQuery {
            topic: services.topic.clone(),
            scope: services.scope.clone(),
            logical_key: b"same-epoch-record".to_vec(),
            include_superseded_versions: true,
        };
        let original_state_request = StatePublishRequest {
            operation_key: b"same-epoch-original-state".to_vec(),
            topic: services.topic.clone(),
            scope: services.scope.clone(),
            priority: Priority::Priority,
            logical_key: state_query.logical_key.clone(),
            payload: b"State before key replacement".to_vec(),
            tombstone: false,
        };
        let original_record_request = RecordPublishRequest {
            operation_key: b"same-epoch-original-record".to_vec(),
            topic: services.topic.clone(),
            scope: services.scope.clone(),
            priority: Priority::Priority,
            logical_key: record_query.logical_key.clone(),
            payload: b"Record before key replacement".to_vec(),
            tombstone: false,
        };
        let original_state = state_handle
            .publish(original_state_request.clone())
            .await
            .expect("publish State before same-epoch rekey");
        let original_record = records
            .publish(original_record_request.clone())
            .await
            .expect("publish Record before same-epoch rekey");
        assert_eq!(
            state_handle
                .query(state_query.clone())
                .await
                .expect("query original State")
                .current
                .expect("original State visible")
                .id,
            original_state.id
        );
        assert_eq!(
            records
                .query(record_query.clone())
                .await
                .expect("query original Record")
                .current
                .expect("original Record visible")
                .id,
            original_record.id
        );

        let rekey = controls
            .publish_scope_rekey(
                ScopeRekeyRequest::new(
                    services.registry.clone(),
                    RegistryGenerationWitness::new(NonZeroU64::new(1).expect("nonzero")),
                    services.scope.clone(),
                    NonZeroU64::new(1).expect("nonzero"),
                    vec![
                        ScopeRekeyRecipient::member(
                            services.authority.identity(),
                            vec![services.topic.clone()],
                        )
                        .expect("authority recipient"),
                        ScopeRekeyRecipient::member(
                            services.member.identity(),
                            vec![services.topic.clone()],
                        )
                        .expect("member recipient"),
                    ],
                )
                .expect("same-epoch rekey request"),
            )
            .await
            .expect("publish same-epoch rekey");
        assert!(rekey.emitted);
        assert!(
            state_handle
                .query(state_query.clone())
                .await
                .expect("query State after key replacement")
                .current
                .is_none(),
            "superseded route-key plaintext is withheld"
        );
        assert!(
            records
                .query(record_query.clone())
                .await
                .expect("query Record after key replacement")
                .current
                .is_none(),
            "superseded route-key plaintext is withheld"
        );
        let state_retry = state_handle
            .publish(original_state_request.clone())
            .await
            .expect("recover exact historical State publication");
        assert!(!state_retry.inserted);
        assert_eq!(state_retry.id, original_state.id);
        let record_retry = records
            .publish(original_record_request.clone())
            .await
            .expect("recover exact historical Record publication");
        assert!(!record_retry.inserted);
        assert_eq!(record_retry.id, original_record.id);

        let replacement_state = state_handle
            .publish(StatePublishRequest {
                operation_key: b"same-epoch-replacement-state".to_vec(),
                topic: services.topic.clone(),
                scope: services.scope.clone(),
                priority: Priority::Immediate,
                logical_key: state_query.logical_key.clone(),
                payload: b"State after key replacement".to_vec(),
                tombstone: false,
            })
            .await
            .expect("publish replacement State");
        let replacement_record = records
            .publish(RecordPublishRequest {
                operation_key: b"same-epoch-replacement-record".to_vec(),
                topic: services.topic.clone(),
                scope: services.scope.clone(),
                priority: Priority::Immediate,
                logical_key: record_query.logical_key.clone(),
                payload: b"Record after key replacement".to_vec(),
                tombstone: false,
            })
            .await
            .expect("publish replacement Record");
        assert_eq!(
            state_handle
                .query(state_query.clone())
                .await
                .expect("query replacement State")
                .current
                .expect("replacement State visible")
                .id,
            replacement_state.id
        );
        assert_eq!(
            records
                .query(record_query.clone())
                .await
                .expect("query replacement Record")
                .current
                .expect("replacement Record visible")
                .id,
            replacement_record.id
        );
        let receipt = running
            .shutdown()
            .await
            .expect("protected mutable shutdown");
        assert_eq!(receipt.controls, 1);
        assert_eq!(receipt.applied_controls, 1);

        let restart_bytes = services
            .authority
            .fresh_bundle()
            .expect("restart authority bundle")
            .to_bytes()
            .expect("encode restart authority bundle");
        let reopened = start_node(protected_config(restart_bytes))
            .await
            .expect("restart protected mutable authority");
        let reopened_state = reopened.selected_state();
        let reopened_records = reopened.selected_records();
        assert_eq!(
            reopened_state
                .query(state_query)
                .await
                .expect("query replacement State after restart")
                .current
                .expect("replacement State retained")
                .id,
            replacement_state.id
        );
        assert_eq!(
            reopened_records
                .query(record_query)
                .await
                .expect("query replacement Record after restart")
                .current
                .expect("replacement Record retained")
                .id,
            replacement_record.id
        );
        let restarted_state_retry = reopened_state
            .publish(original_state_request)
            .await
            .expect("recover exact historical State publication after restart");
        assert!(!restarted_state_retry.inserted);
        assert_eq!(restarted_state_retry.id, original_state.id);
        let restarted_record_retry = reopened_records
            .publish(original_record_request)
            .await
            .expect("recover exact historical Record publication after restart");
        assert!(!restarted_record_retry.inserted);
        assert_eq!(restarted_record_retry.id, original_record.id);
        reopened
            .shutdown()
            .await
            .expect("shutdown restarted protected mutable authority");
        fs::remove_dir_all(state).expect("cleanup protected live mutable state");
    }

    #[tokio::test]
    async fn live_control_pending_gap_returns_policy_unsettled_and_preserves_exact_retry() {
        use std::num::NonZeroU64;

        use crate::control_admin::{ControlAdminErrorKind, RevocationRequest};

        let state = root("live-control-pending-gap");
        fs::create_dir_all(&state).expect("state root");
        let services = control_test_services([0xca; 32]);
        let store = Arc::new(
            Store::open_for_mission(
                state.join(STORE_FILE),
                services.authority.mission_authority_id(),
            )
            .expect("authority store"),
        );
        store
            .require_process_exclusive_lock()
            .expect("exclusive live store");

        let historical = publish_revocation_control_in_store(
            &store,
            &services.authority,
            services.excluded.identity(),
            1,
        )
        .expect("publish historical control");
        assert!(historical.emitted);
        assert_eq!(historical.sequence, 1);

        let StartupEventVerification {
            verifier,
            historical_verifier,
            cache: event_route_cache,
            policy: _,
        } = open_startup_event_verifier_and_cache(&store, &services.authority)
            .expect("open actor-equivalent Event state");
        drop(historical_verifier);
        let application_head = store.control_head().expect("historical control head");
        let custody_clock = NodeCustodyClock::injected([0xca; 16], 1, 1);
        let mut application = SelectedEventNode::from_runtime(
            services.authority.clone(),
            store.clone(),
            verifier,
            application_head,
            custody_clock.clone(),
            event_route_cache.clone(),
        );

        let (head_sequence, head_id) = application_head.expect("nonempty historical head");
        let mut authority = open_replayed_verifier(&store, &services.authority)
            .expect("replay historical authority state");
        let missing = authority
            .seal_chained_revocation_control(
                services.other.identity(),
                1,
                head_sequence + 1,
                Some(*head_id.as_bytes()),
            )
            .expect("seal missing predecessor");
        let missing_id = ControlTransferId::new(
            authority
                .verify_control(&missing)
                .expect("verify missing predecessor")
                .envelope_id(),
        );
        let pending = authority
            .seal_chained_revocation_control(
                services.member.identity(),
                1,
                head_sequence + 2,
                Some(*missing_id.as_bytes()),
            )
            .expect("seal out-of-order successor");
        let verified_pending = authority
            .verify_control(&pending)
            .expect("verify out-of-order successor");
        let pending_outcome = store
            .ingest_verified_control(&verified_pending, &pending)
            .expect("retain out-of-order successor");
        assert!(matches!(pending_outcome, ControlOutcome::Pending { .. }));
        assert_eq!(store.control_stats().expect("pending stats").pending, 1);

        let (fresh_response, fresh_received) = oneshot::channel();
        let fresh_fatal = execute_selected_control_command(
            &mut application,
            &store,
            &services.authority,
            &custody_clock,
            &event_route_cache,
            SelectedControlCommand::PublishRevocation {
                request: RevocationRequest::new(
                    services.excluded.identity(),
                    NonZeroU64::new(2).expect("nonzero"),
                ),
                response: fresh_response,
            },
        );
        assert!(
            fresh_fatal.is_none(),
            "a policy gap is a deferred live state, not an actor failure"
        );
        let fresh_error = fresh_received
            .await
            .expect("fresh caller receives explicit policy result")
            .expect_err("fresh publication cannot cross a pending gap");
        assert_eq!(fresh_error.kind(), ControlAdminErrorKind::PolicyUnsettled);
        assert_eq!(fresh_error.operation(), "publish revocation");

        let (retry_response, retry_received) = oneshot::channel();
        let retry_fatal = execute_selected_control_command(
            &mut application,
            &store,
            &services.authority,
            &custody_clock,
            &event_route_cache,
            SelectedControlCommand::PublishRevocation {
                request: RevocationRequest::new(
                    services.excluded.identity(),
                    NonZeroU64::new(1).expect("nonzero"),
                ),
                response: retry_response,
            },
        );
        assert!(
            retry_fatal.is_none(),
            "an exact historical retry remains nonfatal while policy is deferred"
        );
        let recovered = retry_received
            .await
            .expect("historical caller receives an explicit result")
            .expect("recover historical receipt through pending gap");
        assert_eq!(
            recovered,
            ControlPublicationReceipt {
                emitted: false,
                activated: 0,
                ..historical
            }
        );
        assert!(
            application
                .refresh_runtime_policy()
                .expect("actor-equivalent state remains usable")
                .is_none(),
            "the retained gap continues to defer policy-dependent work"
        );

        let mut receiver = open_replayed_verifier(&store, &services.authority)
            .expect("replay receiver before predecessor arrives");
        let accepted = accept_received_control(
            &store,
            &mut receiver,
            services.authority.identity(),
            missing_id,
            &missing,
        )
        .expect("accept missing predecessor and activate suffix");
        assert!(accepted.retained);
        assert_eq!(accepted.activated, 2);
        assert_eq!(store.control_stats().expect("settled stats").pending, 0);
        assert_eq!(
            refresh_live_control_state(
                &mut application,
                &store,
                &custody_clock,
                &event_route_cache,
            )
            .expect("refresh after predecessor arrival"),
            LiveControlRefresh::Settled
        );

        let (settled_response, settled_received) = oneshot::channel();
        let settled_fatal = execute_selected_control_command(
            &mut application,
            &store,
            &services.authority,
            &custody_clock,
            &event_route_cache,
            SelectedControlCommand::PublishRevocation {
                request: RevocationRequest::new(
                    services.excluded.identity(),
                    NonZeroU64::new(2).expect("nonzero"),
                ),
                response: settled_response,
            },
        );
        assert!(settled_fatal.is_none());
        let settled = settled_received
            .await
            .expect("settled caller receives an explicit result")
            .expect("fresh control succeeds after predecessor arrival");
        assert!(settled.emitted);
        assert_eq!(settled.sequence, 4);

        drop(application);
        drop(receiver);
        drop(authority);
        drop(store);
        fs::remove_dir_all(state).expect("cleanup pending live-control state");
    }

    #[tokio::test]
    async fn saturated_cloned_live_control_retries_do_not_starve_event_status_or_publish() {
        use std::{
            num::NonZeroU64,
            sync::atomic::{AtomicUsize, Ordering as AtomicOrdering},
        };

        use crate::{application::EventPublishRequest, control_admin::RevocationRequest};

        let state = root("saturated-live-control-retries");
        let services = control_test_services([0xcb; 32]);
        let identity = services.authority.identity();
        let mission_authority = services.authority.mission_authority_id();
        let (application_sender, application_receiver) =
            mpsc::channel(APPLICATION_COMMAND_CAPACITY);
        let application_admission = Arc::new(AtomicBool::new(true));
        let events = SelectedEventHandle::new(
            application_sender,
            application_admission.clone(),
            identity,
            mission_authority,
        );
        let (control_sender, control_receiver) = mpsc::channel(CONTROL_COMMAND_CAPACITY);
        let controls =
            SelectedControlHandle::new(control_sender.clone(), identity, mission_authority);
        let (shutdown_sender, shutdown_receiver) = mpsc::channel(1);
        let (ready_sender, ready_receiver) = oneshot::channel();
        let forwarding = SelectedForwardingConfig::default();
        let emission_policy = Arc::new(LiveEmissionPolicy::new(forwarding.emission_policy()));
        let actor = tokio::spawn(run_node_actor_with_forwarding(
            NodeConfig {
                state: state.clone(),
                bind: SocketAddr::from(([127, 0, 0, 1], 0)),
                mission: services.authority.clone(),
                peers: Vec::new(),
                mutable_interests: Default::default(),
                sync_interval: Duration::from_secs(60),
                run_for: None,
                application: NodeApplication::Relay,
            },
            forwarding,
            emission_policy,
            NodeActorChannels::new(
                application_receiver,
                application_admission.clone(),
                control_receiver,
                shutdown_receiver,
                ready_sender,
            ),
        ));
        timeout(Duration::from_secs(10), ready_receiver)
            .await
            .expect("live-control pressure actor readiness deadline")
            .expect("live-control pressure actor readiness");

        let request = RevocationRequest::new(
            services.other.identity(),
            NonZeroU64::new(1).expect("nonzero"),
        );
        let first = timeout(Duration::from_secs(5), controls.publish_revocation(request))
            .await
            .expect("initial live control deadline")
            .expect("publish initial live control");
        assert!(first.emitted);

        let stop_pressure = Arc::new(AtomicBool::new(false));
        let retry_successes = Arc::new(AtomicUsize::new(0));
        let mut retry_tasks = JoinSet::new();
        for _ in 0..CONTROL_COMMAND_BUDGET * 4 {
            let controls = controls.clone();
            let stop_pressure = stop_pressure.clone();
            let retry_successes = retry_successes.clone();
            retry_tasks.spawn(async move {
                while !stop_pressure.load(AtomicOrdering::Acquire) {
                    let receipt = controls
                        .publish_revocation(request)
                        .await
                        .expect("exact live control retry under pressure");
                    assert!(!receipt.emitted);
                    assert_eq!(receipt.transfer_id, first.transfer_id);
                    retry_successes.fetch_add(1, AtomicOrdering::AcqRel);
                }
            });
        }
        timeout(Duration::from_secs(10), async {
            loop {
                if retry_successes.load(AtomicOrdering::Acquire) >= CONTROL_COMMAND_BUDGET * 2
                    && control_sender.capacity() == 0
                {
                    break;
                }
                sleep(Duration::from_millis(1)).await;
            }
        })
        .await
        .expect("cloned retry callers saturate the bounded control queue");

        let status_events = events.clone();
        let publish_events = events.clone();
        let topic = services.topic.clone();
        let scope = services.scope.clone();
        let (status, published) = timeout(Duration::from_secs(5), async move {
            tokio::join!(
                status_events.status(),
                publish_events.publish(EventPublishRequest {
                    operation_key: b"control-pressure-event-publish".to_vec(),
                    predecessor: None,
                    topic,
                    scope,
                    priority: Priority::Immediate,
                    logical_key: b"control-pressure".to_vec(),
                    payload: b"application progress remains bounded".to_vec(),
                    tombstone: false,
                })
            )
        })
        .await
        .expect("Event status and publish must not be starved by control retries");
        status.expect("status progresses through saturated control retries");
        assert!(
            published
                .expect("publish progresses through saturated control retries")
                .inserted
        );

        stop_pressure.store(true, AtomicOrdering::Release);
        timeout(Duration::from_secs(10), async {
            while let Some(result) = retry_tasks.join_next().await {
                result.expect("live control retry pressure task");
            }
        })
        .await
        .expect("retry pressure tasks drain while actor remains live");
        assert!(retry_successes.load(AtomicOrdering::Acquire) >= CONTROL_COMMAND_BUDGET * 2);

        shutdown_sender
            .send(())
            .await
            .expect("request clean pressure-actor shutdown");
        let receipt = timeout(Duration::from_secs(10), actor)
            .await
            .expect("pressure actor shutdown deadline")
            .expect("pressure actor task")
            .expect("clean pressure actor shutdown");
        assert_eq!(receipt.controls, 1);
        assert_eq!(receipt.applied_controls, 1);
        assert_eq!(receipt.pending_controls, 0);
        assert_eq!(receipt.events, 1);
        assert!(!application_admission.load(Ordering::Acquire));

        drop(events);
        drop(controls);
        drop(control_sender);
        fs::remove_dir_all(state).expect("cleanup saturated live-control state");
    }

    #[cfg(unix)]
    #[tokio::test]
    async fn cancelled_enqueued_live_control_remains_actor_owned_and_exactly_retryable() {
        use std::num::NonZeroU64;

        use crate::control_admin::RevocationRequest;

        let state = root("cancelled-enqueued-live-control");
        let services = control_test_services([0xcc; 32]);
        let identity = services.authority.identity();
        let mission_authority = services.authority.mission_authority_id();
        let (application_sender, application_receiver) =
            mpsc::channel(APPLICATION_COMMAND_CAPACITY);
        let application_admission = Arc::new(AtomicBool::new(true));
        let (control_sender, control_receiver) = mpsc::channel(CONTROL_COMMAND_CAPACITY);
        let controls =
            SelectedControlHandle::new(control_sender.clone(), identity, mission_authority);
        let (_shutdown_sender, shutdown_receiver) = mpsc::channel(1);
        let (ready_sender, ready_receiver) = oneshot::channel();
        let (before_loop_ready, before_loop_received) = oneshot::channel();
        let (before_loop_release, release_received) = oneshot::channel();
        let (zeroization_queued, _zeroization_received) = oneshot::channel();
        let forwarding = SelectedForwardingConfig::default();
        let emission_policy = Arc::new(LiveEmissionPolicy::new(forwarding.emission_policy()));
        let actor = tokio::spawn(run_node_actor_inner(
            NodeConfig {
                state: state.clone(),
                bind: SocketAddr::from(([127, 0, 0, 1], 0)),
                mission: services.authority.clone(),
                peers: Vec::new(),
                mutable_interests: Default::default(),
                sync_interval: Duration::from_secs(60),
                run_for: None,
                application: NodeApplication::Relay,
            },
            forwarding,
            emission_policy,
            NodeActorChannels {
                application_receiver,
                application_admission: application_admission.clone(),
                control_receiver,
                shutdown_receiver,
                ready: ready_sender,
                test_control: Some(RunNodeActorTestControl {
                    before_loop_ready,
                    before_loop_release: release_received,
                    zeroization_queued,
                    blob_worker_fatal_on_shutdown: false,
                    blob_final_read_gate: None,
                }),
            },
        ));
        timeout(Duration::from_secs(10), ready_receiver)
            .await
            .expect("paused actor readiness deadline")
            .expect("paused actor readiness");
        timeout(Duration::from_secs(5), before_loop_received)
            .await
            .expect("actor reaches deterministic pre-loop pause")
            .expect("pre-loop pause remains connected");

        let request = RevocationRequest::new(identity, NonZeroU64::new(1).expect("nonzero"));
        let cancelled = tokio::spawn({
            let controls = controls.clone();
            async move { controls.publish_revocation(request).await }
        });
        timeout(Duration::from_secs(5), async {
            while control_sender.capacity() != 0 {
                sleep(Duration::from_millis(1)).await;
            }
        })
        .await
        .expect("control command is enqueued before caller cancellation");
        cancelled.abort();
        assert!(
            cancelled
                .await
                .expect_err("cancelled caller task cannot complete")
                .is_cancelled()
        );

        before_loop_release
            .send(())
            .expect("release actor after caller cancellation");
        let actor_error = timeout(Duration::from_secs(10), actor)
            .await
            .expect("cancelled self-revocation actor teardown deadline")
            .expect("cancelled self-revocation actor task")
            .expect_err("actor must close after committing self-revocation");
        assert!(matches!(actor_error, NodeError::Revoked(principal) if principal == identity));
        assert!(!application_admission.load(Ordering::Acquire));

        let store = Store::open_for_mission(state.join(STORE_FILE), mission_authority)
            .expect("reopen cancelled self-revocation store");
        let (durable_sequence, durable_transfer) = store
            .control_head()
            .expect("read cancelled self-revocation head")
            .expect("cancelled self-revocation committed a durable head");
        let stats = store.control_stats().expect("cancelled command stats");
        assert_eq!(stats.controls, 1);
        assert_eq!(stats.applied, 1);
        assert_eq!(stats.pending, 0);
        drop(store);

        let recovered =
            publish_revocation_control(&state, &services.authority, identity, request.generation())
                .expect("stopped exact retry recovers cancelled caller receipt");
        assert!(!recovered.emitted);
        assert_eq!(recovered.sequence, durable_sequence);
        assert_eq!(recovered.transfer_id, durable_transfer);

        drop(application_sender);
        drop(controls);
        drop(control_sender);
        fs::remove_dir_all(state).expect("cleanup cancelled live-control state");
    }

    #[tokio::test]
    async fn live_self_revocation_returns_receipt_before_actor_teardown() {
        use std::num::NonZeroU64;

        use crate::control_admin::{ControlAdminErrorKind, RevocationRequest};

        let state = root("live-self-revocation");
        let services = control_test_services([0xc9; 32]);
        let local = services.authority.identity();
        let running = start_node(NodeConfig::new(
            &state,
            SocketAddr::from(([127, 0, 0, 1], 0)),
            services.authority.clone(),
        ))
        .await
        .expect("start authority runtime");
        let controls = running.selected_controls();
        let receipt = controls
            .publish_revocation(RevocationRequest::new(
                local,
                NonZeroU64::new(1).expect("nonzero"),
            ))
            .await
            .expect("self-revocation returns committed receipt");
        assert!(receipt.emitted);
        assert_eq!(receipt.activated, 1);

        let actor_error = timeout(Duration::from_secs(10), running.wait())
            .await
            .expect("self-revoked actor stops promptly")
            .expect_err("self-revoked actor fails closed");
        assert!(matches!(actor_error, NodeError::Revoked(principal) if principal == local));
        assert_eq!(
            controls
                .publish_revocation(RevocationRequest::new(
                    services.other.identity(),
                    NonZeroU64::new(1).expect("nonzero"),
                ))
                .await
                .expect_err("post-teardown control is rejected")
                .kind(),
            ControlAdminErrorKind::StateUnavailable
        );
        let store = Store::open_for_mission(
            state.join(STORE_FILE),
            services.authority.mission_authority_id(),
        )
        .expect("reopen self-revoked store");
        assert_eq!(store.control_stats().expect("control stats").applied, 1);
        drop(store);
        fs::remove_dir_all(state).expect("cleanup self-revocation state");
    }

    fn seal_test_revoke_then_rekey(
        services: &ControlTestServices,
        revoked: NodeId,
        recipients: Vec<ScopeRekeyRecipient>,
    ) -> (Vec<u8>, Vec<u8>) {
        let mut authority = open_test_sealer(&services.authority);
        let first = authority
            .seal_chained_revocation_control(revoked, 1, 1, None)
            .expect("seal first revocation");
        let first_id = authority
            .verify_control(&first)
            .expect("verify first revocation")
            .envelope_id();
        let (second, _) = authority
            .seal_chained_scope_rekey_control_from_registry(
                &services.registry,
                0,
                services.scope.clone(),
                2,
                recipients,
                2,
                Some(first_id),
            )
            .expect("seal second rekey");
        (first, second)
    }

    fn publish_test_epoch_two_event(
        store: &Store,
        sealer: &mut ReferenceEnvelopeSealer,
        services: &ControlTestServices,
    ) -> StoredEvent {
        let policy = store
            .control_policy_snapshot()
            .expect("settled epoch policy");
        let reservation = store
            .reserve_event_with_policy(&policy, sealer.identity(), &services.topic, &services.scope)
            .expect("reserve epoch-two Event");
        let payload = b"selected epoch two";
        let header = reservation
            .header(
                Priority::Immediate,
                b"epoch-two".to_vec(),
                None,
                payload.len() as u64,
                false,
                2,
            )
            .expect("epoch-two header");
        let sealed = sealer
            .seal_event(&header, payload)
            .expect("seal epoch-two Event");
        let route = sealer
            .verify_event(&sealed.bytes)
            .expect("verify local epoch-two route");
        let EventContentVerification::ContentVerified { event, .. } = sealer
            .verify_event_content(route, &sealed.bytes)
            .expect("verify local epoch-two content")
        else {
            panic!("authority must retain epoch-two content grant");
        };
        store
            .commit_reserved_event_with_policy(&policy, &reservation, &event, &sealed.bytes)
            .expect("commit epoch-two Event");
        let transfer_id = EventTransferId::new(event.envelope_id());
        match store
            .get_transfer_with_policy(&policy, transfer_id)
            .expect("reload epoch-two Event")
        {
            Some(StoredEventTransfer::Accepted(event)) => event,
            _ => panic!("epoch-two Event is not semantically accepted"),
        }
    }

    fn publish_test_epoch_one_event(
        store: &Store,
        sealer: &mut ReferenceEnvelopeSealer,
        topic: &Topic,
        scope: &Scope,
        logical_key: &[u8],
    ) -> EventTransferId {
        let reservation = store
            .reserve_event(sealer.identity(), topic, scope)
            .expect("reserve epoch-one test Event");
        let payload = logical_key;
        let header = reservation
            .header(
                Priority::Routine,
                logical_key.to_vec(),
                None,
                payload.len() as u64,
                false,
                1,
            )
            .expect("epoch-one test header");
        let sealed = sealer
            .seal_event(&header, payload)
            .expect("seal epoch-one test Event");
        let route = sealer
            .verify_event(&sealed.bytes)
            .expect("verify epoch-one test route");
        let EventContentVerification::ContentVerified { event, .. } = sealer
            .verify_event_content(route, &sealed.bytes)
            .expect("verify epoch-one test content")
        else {
            panic!("test member lost content grant");
        };
        store
            .commit_reserved_event(&reservation, &event, &sealed.bytes)
            .expect("commit epoch-one test Event");
        EventTransferId::new(event.envelope_id())
    }

    struct TestCustodyPublication<'a> {
        operation: &'a [u8],
        topic: &'a Topic,
        scope: &'a Scope,
        priority: Priority,
        ttl_ms: Option<u64>,
        sample: CustodySample,
        payload: &'a [u8],
        tombstone: bool,
    }

    fn publish_test_custody_event(
        store: &Store,
        sealer: &mut ReferenceEnvelopeSealer,
        publication: TestCustodyPublication<'_>,
    ) -> StoredEvent {
        let TestCustodyPublication {
            operation,
            topic,
            scope,
            priority,
            ttl_ms,
            sample,
            payload,
            tombstone,
        } = publication;
        let operation = EventOperationKey::new(operation.to_vec()).expect("operation key");
        let policy = store.control_policy_snapshot().expect("settled policy");
        publish_selected_event_once(
            store,
            &policy,
            sealer,
            SelectedEventPublish {
                operation: &operation,
                predecessor: None,
                topic,
                scope,
                priority,
                ttl_ms,
                custody_sample: Some(sample),
                logical_key: payload,
                payload,
                tombstone,
            },
        )
        .expect("publish custody Event")
        .0
    }

    fn publish_test_state(
        store: &Store,
        sealer: &mut ReferenceEnvelopeSealer,
        topic: &Topic,
        scope: &Scope,
        logical_key: &[u8],
        payload: &[u8],
    ) -> StateTransferId {
        let policy = store
            .control_policy_snapshot()
            .expect("settled State policy");
        let reservation = store
            .reserve_state_with_policy(&policy, sealer.identity(), topic, scope)
            .expect("State reservation");
        let header = reservation
            .header(
                Priority::Routine,
                logical_key.to_vec(),
                u64::try_from(payload.len()).expect("State payload length"),
                false,
                1,
            )
            .expect("State header");
        let sealed = sealer
            .seal_state(&header, payload)
            .expect("seal test State")
            .bytes;
        let route = sealer.verify_state(&sealed).expect("verify test State");
        let state = match sealer
            .verify_state_content(route, &sealed)
            .expect("verify test State content")
        {
            StateContentVerification::ContentVerified { state, .. } => state,
            StateContentVerification::RouteOnly(_) => panic!("test State lacks content grant"),
        };
        let transfer_id = StateTransferId::new(state.envelope_id());
        store
            .commit_reserved_state_with_policy(&policy, &reservation, &state, &sealed)
            .expect("commit test State");
        transfer_id
    }

    fn publish_ordered_starvation_states(
        store: &Store,
        sealer: &mut ReferenceEnvelopeSealer,
        topic: &Topic,
        scope: &Scope,
        label: &str,
    ) -> (StateTransferId, StateTransferId) {
        let policy = store
            .control_policy_snapshot()
            .expect("settled starvation policy");
        let poison_payload = vec![0xa5; 4 * 1024];
        let poison = (0..4_096u32)
            .find_map(|attempt| {
                let reservation = store
                    .reserve_state_with_policy(&policy, sealer.identity(), topic, scope)
                    .expect("poison State reservation");
                let logical_key = format!("cursor/{label}/poison/{attempt}").into_bytes();
                let header = reservation
                    .header(
                        Priority::Routine,
                        logical_key,
                        u64::try_from(poison_payload.len()).expect("poison payload length"),
                        false,
                        1,
                    )
                    .expect("poison State header");
                let sealed = sealer
                    .seal_state(&header, &poison_payload)
                    .expect("seal poison State")
                    .bytes;
                let route = sealer
                    .verify_state(&sealed)
                    .expect("verify poison State route");
                let state = match sealer
                    .verify_state_content(route, &sealed)
                    .expect("verify poison State content")
                {
                    StateContentVerification::ContentVerified { state, .. } => state,
                    StateContentVerification::RouteOnly(_) => {
                        panic!("test poison State lacks content grant")
                    }
                };
                let id = StateTransferId::new(state.envelope_id());
                if id.as_bytes()[0] > 0x40 {
                    return None;
                }
                store
                    .commit_reserved_state_with_policy(&policy, &reservation, &state, &sealed)
                    .expect("commit poison State");
                Some(id)
            })
            .expect("bounded poison search finds a low transfer ID");

        let small_payload = [0x5a];
        let small = (0..4_096u32)
            .find_map(|attempt| {
                let reservation = store
                    .reserve_state_with_policy(&policy, sealer.identity(), topic, scope)
                    .expect("small State reservation");
                let logical_key = format!("cursor/{label}/small/{attempt}").into_bytes();
                let header = reservation
                    .header(
                        Priority::Routine,
                        logical_key,
                        u64::try_from(small_payload.len()).expect("small payload length"),
                        false,
                        1,
                    )
                    .expect("small State header");
                let sealed = sealer
                    .seal_state(&header, &small_payload)
                    .expect("seal small State")
                    .bytes;
                let route = sealer
                    .verify_state(&sealed)
                    .expect("verify small State route");
                let state = match sealer
                    .verify_state_content(route, &sealed)
                    .expect("verify small State content")
                {
                    StateContentVerification::ContentVerified { state, .. } => state,
                    StateContentVerification::RouteOnly(_) => {
                        panic!("test small State lacks content grant")
                    }
                };
                let id = StateTransferId::new(state.envelope_id());
                if id <= poison {
                    return None;
                }
                store
                    .commit_reserved_state_with_policy(&policy, &reservation, &state, &sealed)
                    .expect("commit small State");
                Some(id)
            })
            .expect("bounded small search finds a successor transfer ID");
        (poison, small)
    }

