    #[cfg(feature = "nearby-discovery")]
    #[test]
    fn nearby_peer_parser_round_trips_only_the_identity_pair() {
        let peer = nearby_peer(800);
        let encoded = peer.to_string();
        assert_eq!(
            encoded.parse::<MissionNearbyPeer>().expect("round trip"),
            peer
        );
        assert!(
            !encoded.contains('@'),
            "nearby syntax must not contain a socket"
        );

        let mission = format_node_id(peer.mission);
        for malformed in [
            String::new(),
            peer.carrier.to_string(),
            format!("{}={mission}=extra", peer.carrier),
            format!("not-an-endpoint={mission}"),
            format!("{}=abcd", peer.carrier),
        ] {
            assert!(
                malformed.parse::<MissionNearbyPeer>().is_err(),
                "accepted malformed nearby peer: {malformed}"
            );
        }
    }

    #[cfg(feature = "nearby-discovery")]
    #[test]
    fn nearby_window_and_roster_bounds_fail_closed() {
        let peer = nearby_peer(801);
        assert!(
            SelectedForwardingConfig::default()
                .with_nearby_discovery(vec![peer], Duration::ZERO)
                .is_err()
        );
        assert!(
            SelectedForwardingConfig::default()
                .with_nearby_discovery(vec![peer], Duration::from_nanos(1))
                .is_err(),
            "sub-second windows must not be truncated to a disabled receipt"
        );
        assert!(
            SelectedForwardingConfig::default()
                .with_nearby_discovery(vec![peer], Duration::from_millis(1_500))
                .is_err(),
            "fractional-second windows must not be truncated in readiness receipts"
        );
        assert!(
            SelectedForwardingConfig::default()
                .with_nearby_discovery(Vec::new(), Duration::from_secs(1))
                .is_err()
        );
        assert!(
            SelectedForwardingConfig::default()
                .with_nearby_discovery(vec![peer], MAX_NEARBY_DISCOVERY_WINDOW)
                .is_ok(),
            "the exact documented maximum is valid"
        );
        assert!(
            SelectedForwardingConfig::default()
                .with_nearby_discovery(
                    vec![peer],
                    MAX_NEARBY_DISCOVERY_WINDOW + Duration::from_nanos(1),
                )
                .is_err()
        );
    }

    #[cfg(feature = "nearby-discovery")]
    #[test]
    fn automatic_nearby_is_rosterless_bounded_and_exclusive() {
        for invalid in [
            Duration::ZERO,
            Duration::from_millis(1_500),
            MAX_NEARBY_DISCOVERY_WINDOW + Duration::from_secs(1),
        ] {
            assert!(
                SelectedForwardingConfig::default()
                    .with_automatic_nearby_discovery(invalid)
                    .is_err()
            );
        }
        let forwarding = SelectedForwardingConfig::default()
            .with_automatic_nearby_discovery(MAX_NEARBY_DISCOVERY_WINDOW)
            .expect("automatic nearby maximum window");
        assert!(forwarding.automatic_nearby_discovery());
        assert_eq!(
            forwarding.nearby_discovery_window(),
            Some(MAX_NEARBY_DISCOVERY_WINDOW)
        );
        assert!(forwarding.nearby_discovery_ipv4_interfaces().is_empty());

        let multihomed = SelectedForwardingConfig::default()
            .with_automatic_nearby_discovery_on_ipv4_interfaces(
                MAX_NEARBY_DISCOVERY_WINDOW,
                vec![
                    Ipv4Addr::new(10, 0, 0, 2),
                    Ipv4Addr::new(10, 0, 0, 1),
                    Ipv4Addr::new(10, 0, 0, 2),
                ],
            )
            .expect("explicit multi-interface automatic discovery");
        assert_eq!(
            multihomed.nearby_discovery_ipv4_interfaces(),
            [Ipv4Addr::new(10, 0, 0, 1), Ipv4Addr::new(10, 0, 0, 2)]
        );
        for invalid in [
            Ipv4Addr::UNSPECIFIED,
            Ipv4Addr::new(224, 0, 0, 1),
            Ipv4Addr::BROADCAST,
        ] {
            assert!(
                SelectedForwardingConfig::default()
                    .with_automatic_nearby_discovery_on_ipv4_interfaces(
                        Duration::from_secs(1),
                        vec![invalid],
                    )
                    .is_err(),
                "accepted invalid discovery interface {invalid}"
            );
        }
        let too_many_interfaces = (1..=MAX_NEARBY_DISCOVERY_IPV4_INTERFACES + 1)
            .map(|suffix| {
                Ipv4Addr::new(
                    10,
                    1,
                    0,
                    u8::try_from(suffix).expect("test interface range"),
                )
            })
            .collect();
        assert!(
            SelectedForwardingConfig::default()
                .with_automatic_nearby_discovery_on_ipv4_interfaces(
                    Duration::from_secs(1),
                    too_many_interfaces,
                )
                .is_err()
        );

        let config = nearby_node_config("nearby-auto-rosterless", Vec::new());
        let (allowed, configured) =
            configured_nearby_peers(&config, &forwarding).expect("rosterless configuration");
        assert!(allowed.is_empty());
        assert!(configured.is_empty());

        let manual = nearby_node_config(
            "nearby-auto-manual-rejected",
            vec![expected_peer(8_101, 28_101)],
        );
        let error = configured_nearby_peers(&manual, &forwarding)
            .expect_err("automatic discovery must not accept direct peers");
        assert!(error.to_string().contains("direct peer routes"));
    }

    #[cfg(feature = "nearby-discovery")]
    #[test]
    fn automatic_nearby_admission_bounds_missions_without_trusting_carrier_pairing() {
        let local = [0xa1; 32];
        let admission = AutomaticNearbyAdmission::new(local);
        let first_mission = [1; 32];
        admission
            .admit(MissionPeerBinding::new(
                aster_iroh::SecretKey::generate().public(),
                first_mission,
            ))
            .expect("first mission admission");
        admission
            .admit(MissionPeerBinding::new(
                aster_iroh::SecretKey::generate().public(),
                first_mission,
            ))
            .expect("same authenticated mission behind another carrier remains one member");

        for index in 2..=MAX_AUTOMATIC_NEARBY_CANDIDATES {
            let mut mission = [0u8; 32];
            mission[..8].copy_from_slice(&(index as u64).to_be_bytes());
            admission
                .admit(MissionPeerBinding::new(
                    aster_iroh::SecretKey::generate().public(),
                    mission,
                ))
                .expect("bounded authenticated mission admission");
        }
        let error = admission
            .admit(MissionPeerBinding::new(
                aster_iroh::SecretKey::generate().public(),
                [0xfe; 32],
            ))
            .expect_err("mission capacity must fail before inventory");
        assert!(
            error
                .to_string()
                .contains("capacity reached before inventory")
        );

        let local_error = AutomaticNearbyAdmission::new(local)
            .admit(MissionPeerBinding::new(
                aster_iroh::SecretKey::generate().public(),
                local,
            ))
            .expect_err("local mission identity must not become a peer");
        assert!(local_error.to_string().contains("local mission identity"));
    }

